  const priority = calculatePriorities(graph)

  // Initialize workers
  const workers = Array.from({ length: workerCount }, () => ({
    freeAt: 0,
    tasks: []
  }))

  const finished = {}
  const taskCount = Object.keys(graph).length

  while (Object.keys(finished).length < taskCount) {
    // Find the earliest time a worker is free
    let currentTime = Math.min(...workers.map(w => w.freeAt))

    // Keep assigning tasks while a worker is free and tasks are ready
    while (true) {
      // Find a free worker (smallest index)
      let freeWorkerIdx = -1
      for (let i = 0; i < workers.length; i++) {
        if (workers[i].freeAt <= currentTime) {
          freeWorkerIdx = i
          break
        }
      }

      if (freeWorkerIdx === -1) break  // No free worker at this time

      // Find all ready tasks at this time
      const ready = []
      for (const name in graph) {
        if (name in finished) continue

        const node = graph[name]
        let allDepsFinished = true

        for (const dep of node.dependencies) {
          if (!(dep in finished) || finished[dep].finish > currentTime) {
            allDepsFinished = false
            break
          }
        }

        if (allDepsFinished) {
          ready.push(name)
        }
      }

      if (ready.length === 0) break  // No ready tasks at this time

      // Select task with highest priority, breaking ties by ascending name
      let bestTask = null
      let bestPriority = -1

      for (const task of ready) {
        if (priority[task] > bestPriority || 
            (priority[task] === bestPriority && (!bestTask || task < bestTask))) {
          bestTask = task
          bestPriority = priority[task]
        }
      }

      // Assign task to worker
      const node = graph[bestTask]
      const start = currentTime
      const finish = start + node.cost

      workers[freeWorkerIdx].tasks.push({
        name: bestTask,
        start,
        finish
      })

      workers[freeWorkerIdx].freeAt = finish
      finished[bestTask] = { finish }
    }
  }

  // Output results
  let makespan = 0
  for (let i = 0; i < workers.length; i++) {
    const worker = workers[i]
    let line = `worker ${i}:`

    for (const task of worker.tasks) {
      line += ` ${task.name}@${task.start}-${task.finish}`
      makespan = Math.max(makespan, task.finish)
    }

    process.stdout.write(line + '\n')
  }

