{"file_path":"src/cli.js","old_string":"function parseInput(input) {
  const tasks = {}
  const deps = {}
  const lineErrors = []

  let lineNum = 0
  const lines = input.split('\n')

  for (const rawLine of lines) {
    lineNum++

    // Trim and ignore empty lines and comments
    const line = rawLine.trim()
    if (!line || line.startsWith('#')) {
      continue
    }

    // Split on whitespace
    const words = line.split(/\s+/)
    if (words.length === 0) continue

    const directive = words[0]

    if (directive === 'task') {
      if (words.length !== 3) {
        lineErrors.push(`error: line ${lineNum}: expected task <name> <cost>`)
        continue
      }

      const name = words[1]
      const costStr = words[2]

      // Validate name
      if (!/^[A-Za-z0-9_.\-]+$/.test(name)) {
        lineErrors.push(`error: line ${lineNum}: invalid task name ${name}`)
        continue
      }

      // Validate cost - unsigned decimal integer
      if (!/^\d+$/.test(costStr)) {
        lineErrors.push(`error: line ${lineNum}: cost must be a non-negative integer`)
        continue
      }

      // Check for duplicate task
      if (name in tasks) {
        lineErrors.push(`error: line ${lineNum}: task ${name} is declared twice`)
        continue
      }

      const cost = parseInt(costStr)
      tasks[name] = cost
      if (!(name in deps)) {
        deps[name] = []
      }
    } else if (directive === 'dep') {
      if (words.length < 3) {
        lineErrors.push(`error: line ${lineNum}: expected dep <name> <dependency>...`)
        continue
      }

      const name = words[1]
      const depList = words.slice(2)

      // Initialize deps entry if not present
      if (!(name in deps)) {
        deps[name] = []
      }

      // Add dependencies (avoid duplicates)
      for (const dep of depList) {
        if (!deps[name].includes(dep)) {
          deps[name].push(dep)
        }
      }
    } else {
      lineErrors.push(`error: line ${lineNum}: unknown directive ${directive}`)
      continue
    }
  }

  return { tasks, deps, lineErrors }
}","new_string":"function parseInput(input) {
  const tasks = {}
  const deps = {}
  const lineErrors = []
  const depOrder = [] // Track order of dep references for error checking

  let lineNum = 0
  const lines = input.split('\n')

  for (const rawLine of lines) {
    lineNum++

    // Trim and ignore empty lines and comments
    const line = rawLine.trim()
    if (!line || line.startsWith('#')) {
      continue
    }

    // Split on whitespace
    const words = line.split(/\s+/)
    if (words.length === 0) continue

    const directive = words[0]

    if (directive === 'task') {
      if (words.length !== 3) {
        lineErrors.push(`error: line ${lineNum}: expected task <name> <cost>`)
        continue
      }

      const name = words[1]
      const costStr = words[2]

      // Validate name
      if (!/^[A-Za-z0-9_.\-]+$/.test(name)) {
        lineErrors.push(`error: line ${lineNum}: invalid task name ${name}`)
        continue
      }

      // Validate cost - unsigned decimal integer
      if (!/^\d+$/.test(costStr)) {
        lineErrors.push(`error: line ${lineNum}: cost must be a non-negative integer`)
        continue
      }

      // Check for duplicate task
      if (name in tasks) {
        lineErrors.push(`error: line ${lineNum}: task ${name} is declared twice`)
        continue
      }

      const cost = parseInt(costStr)
      tasks[name] = cost
      if (!(name in deps)) {
        deps[name] = []
      }
    } else if (directive === 'dep') {
      if (words.length < 3) {
        lineErrors.push(`error: line ${lineNum}: expected dep <name> <dependency>...`)
        continue
      }

      const name = words[1]
      const depList = words.slice(2)

      // Initialize deps entry if not present
      if (!(name in deps)) {
        deps[name] = []
      }

      // Add dependencies (avoid duplicates) and track order
      for (const dep of depList) {
        if (!deps[name].includes(dep)) {
          deps[name].push(dep)
          depOrder.push(dep) // Track for error checking
        }
      }
    } else {
      lineErrors.push(`error: line ${lineNum}: unknown directive ${directive}`)
      continue
    }
  }

  return { tasks, deps, lineErrors, depOrder }
}"}

