 * Recursive-descent parser for formula bodies, producing an AST.
 *
 * Grammar (loosest to tightest):
 *   comparison := additive (COMPOP additive)*
 *   additive   := multiplicative (('+'|'-') multiplicative)*
 *   multiplicative := power (('*'|'/') power)*
 *   power      := unary ('^' power)?             (right-assoc)
 *   unary      := ('-'|'+') unary | primary
 *   primary    := NUMBER | '(' comparison ')' | TRUE | FALSE | call | word
 *
 * Call arguments are each either a range (WORD ':' WORD) or a comparison
 * expression; ranges are only accepted directly in that position.
 */

import { tokenize, LexError } from './lexer.js'

export class GrammarError extends Error {}

const COMPARE_OPS = new Set(['=', '<>', '<', '<=', '>', '>='])
const CALL_NAMES = new Set(['SUM', 'MIN', 'MAX', 'COUNT', 'AVG', 'ABS', 'IF'])

class TokenStream {
  constructor(tokens) {
    this.tokens = tokens
    this.pos = 0
  }
  peek() {
    return this.tokens[this.pos]
  }
  next() {
    return this.tokens[this.pos++]
  }
  atEnd() {
    return this.pos >= this.tokens.length
  }
}

export function parseFormula(body) {
  let tokens
  try {
    tokens = tokenize(body)
  } catch (e) {
    if (e instanceof LexError) return null
    throw e
  }
  const ts = new TokenStream(tokens)
  try {
    const node = parseComparison(ts)
    if (!ts.atEnd()) return null
    return node
  } catch (e) {
    if (e instanceof GrammarError) return null
    throw e
  }
}

function parseComparison(ts) {
  let left = parseAdditive(ts)
  while (true) {
    const tok = ts.peek()
    if (tok && tok.type === 'OP' && COMPARE_OPS.has(tok.v)) {
      ts.next()
      const right = parseAdditive(ts)
      left = { type: 'BinOp', op: tok.v, left, right }
    } else {
      break
    }
  }
  return left
}

function parseAdditive(ts) {
  let left = parseMultiplicative(ts)
  while (true) {
    const tok = ts.peek()
    if (tok && tok.type === 'OP' && (tok.v === '+' || tok.v === '-')) {
      ts.next()
      const right = parseMultiplicative(ts)
      left = { type: 'BinOp', op: tok.v, left, right }
    } else {
      break
    }
  }
  return left
}

function parseMultiplicative(ts) {
  let left = parsePower(ts)
  while (true) {
    const tok = ts.peek()
    if (tok && tok.type === 'OP' && (tok.v === '*' || tok.v === '/')) {
      ts.next()
      const right = parsePower(ts)
      left = { type: 'BinOp', op: tok.v, left, right }
    } else {
      break
    }
  }
  return left
}

function parsePower(ts) {
  const base = parseUnary(ts)
  const tok = ts.peek()
  if (tok && tok.type === 'OP' && tok.v === '^') {
    ts.next()
    const right = parsePower(ts)
    return { type: 'BinOp', op: '^', left: base, right }
