 * Parses the raw sheet text into a map of canonical address -> content.
 */

import { parseAddressShape } from './address.js'

export class SheetError extends Error {
  constructor(line, message) {
    super(message)
    this.line = line
  }
}

export function parseSheet(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const cells = new Map() // canon -> content string
  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const raw = lines[i]
    const stripped = raw.replace(/^[ \t]+/, '')
    if (stripped === '' || stripped.startsWith('#')) continue

    let j = 0
    while (j < stripped.length && stripped[j] !== ' ' && stripped[j] !== '\t') j++
    const addrToken = stripped.slice(0, j)
    let k = j
    while (k < stripped.length && (stripped[k] === ' ' || stripped[k] === '\t')) {
      k++
      break // skip one run: only need to know we consumed the whitespace run
    }
    // consume the rest of the whitespace run
    while (k < stripped.length && (stripped[k - 1] === ' ' || stripped[k - 1] === '\t') && (stripped[k] === ' ' || stripped[k] === '\t')) {
      k++
    }
    const content = stripped.slice(k)

    const shape = parseAddressShape(addrToken)
    if (!shape.valid) {
      throw new SheetError(lineNo, `error: line ${lineNo}: invalid cell address ${addrToken}`)
    }
    if (cells.has(shape.canon)) {
      throw new SheetError(lineNo, `error: line ${lineNo}: cell ${shape.canon} is declared twice`)
    }
    cells.set(shape.canon, content)
  }
  return cells
}
"}

