{"file_path":"src/engine.js","content":"/**
 * Voting engine that runs instant-runoff voting rounds.
 */

export class VotingEngine {
  constructor(election) {
    this.candidates = election.candidates
    this.ballots = election.ballots
    this.roundHistory = [] // Track vote counts across rounds for tiebreaking
  }

  runElection() {
    const continuing = new Set(this.candidates)
    const rounds = []
    let roundNumber = 0

    while (true) {
      roundNumber++

      // Count votes in this round
      const votes = this.countRound(continuing)
      const exhausted = this.countExhausted(continuing)
      const activeTotal = this.getActiveTotal(votes)

      // Record the round
      const roundData = {
        number: roundNumber,
        votes: new Map(votes),
        exhausted,
        activeTotal,
        eliminated: null
      }

      // Store vote counts for tiebreaking
      this.roundHistory.push(new Map(votes))

      // Check for winner
      for (const [candidate, count] of votes) {
        if (count * 2 > activeTotal) {
          roundData.eliminated = null
          rounds.push(roundData)
          return { rounds, winner: candidate }
        }
      }

      // Check for no winner (no active votes)
      if (activeTotal === 0) {
        roundData.eliminated = null
        rounds.push(roundData)
        return { rounds, winner: null }
      }

      // Eliminate someone
      const toEliminate = this.findCandidateToEliminate(votes, continuing)
      continuing.delete(toEliminate)
      roundData.eliminated = toEliminate

      rounds.push(roundData)
    }
  }

  countRound(continuing) {
    const votes = new Map()

    // Initialize all continuing candidates with 0
    for (const candidate of continuing) {
      votes.set(candidate, 0)
    }

    // Count each ballot for the first continuing candidate it names
    for (const ballot of this.ballots) {
      for (const choice of ballot.choices) {
        if (continuing.has(choice)) {
          votes.set(choice, (votes.get(choice) || 0) + ballot.count)
          break
        }
      }
    }

    return Array.from(votes.entries())
  }

  countExhausted(continuing) {
    let count = 0

    for (const ballot of this.ballots) {
      // Check if all choices are eliminated
      let hasAnyContinuing = false
      for (const choice of ballot.choices) {
        if (continuing.has(choice)) {
          hasAnyContinuing = true
          break
        }
      }

      if (!hasAnyContinuing) {
        count += ballot.count
      }
    }

    return count
  }

  getActiveTotal(votes) {
    let total = 0
    for (const [, count] of votes) {
      total += count
    }
    return total
  }

  findCandidateToEliminate(votes, continuing) {
    // Find candidates with fewest votes in this round
    const voteMap = new Map(votes)
    let minVotes = Math.min(...Array.from(continuing).map(c => voteMap.get(c)))
    let candidates = Array.from(continuing).filter(c => voteMap.get(c) === minVotes)

    if (candidates.length === 1) {
      return candidates[0]
    }

    // Use tiebreaking: compare across rounds
    for (let roundIdx = 0; roundIdx < this.roundHistory.length; roundIdx++) {
      const roundVotes = this.roundHistory[roundIdx]

      // Find the minimum votes among tied candidates in this round
      let minInRound = Math.min(...candidates.map(c => roundVotes.get(c)))
      const newCandidates = candidates.filter(c => roundVotes.get(c) === minInRound)

      if (newCandidates.length < candidates.length) {
        candidates = newCandidates
      }

      if (candidates.length === 1) {
        return candidates[0]
      }
    }

    // No round separates them, eliminate by name (sort last by code point)
    candidates.sort((a, b) => b.localeCompare(a))
    return candidates[0]
  }
}
"}

