 * Parsing of the election description read from standard input.
 */

export class ParseError extends Error {
  constructor(line, message) {
    super(message)
    this.line = line
  }
}

const NAME_RE = /^[A-Za-z0-9_-]+$/
const COUNT_RE = /^[1-9][0-9]*$/

export function parseElection(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  let sawCandidates = false
  let sawBallot = false
  let candidates = null
  let candidateSet = null
  const ballots = []

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue

    const tokens = line.split(/\s+/)
    const directive = tokens[0]

    if (directive === 'candidates') {
      if (sawCandidates || sawBallot) {
        throw new ParseError(lineNo, 'candidates must be declared once, before any ballot')
      }
      if (tokens.length < 2) {
        throw new ParseError(lineNo, 'expected candidates <name>...')
      }
      const names = tokens.slice(1)
      const seen = new Set()
      for (const name of names) {
        if (!NAME_RE.test(name)) {
          throw new ParseError(lineNo, `invalid candidate name ${name}`)
        }
        if (seen.has(name)) {
          throw new ParseError(lineNo, `candidate ${name} is declared twice`)
        }
        seen.add(name)
      }
      candidates = names
      candidateSet = seen
      sawCandidates = true
    } else if (directive === 'ballot') {
      if (!sawCandidates) {
        throw new ParseError(lineNo, 'candidates must be declared once, before any ballot')
      }
      if (tokens.length < 3) {
        throw new ParseError(lineNo, 'expected ballot <count> <candidate>...')
      }
      const countStr = tokens[1]
      if (!COUNT_RE.test(countStr)) {
        throw new ParseError(lineNo, 'count must be a positive integer')
      }
      const count = Number(countStr)
      const names = tokens.slice(2)
      const seenBallot = new Set()
      for (const name of names) {
        if (!candidateSet.has(name)) {
          throw new ParseError(lineNo, `unknown candidate ${name}`)
        }
        if (seenBallot.has(name)) {
          throw new ParseError(lineNo, `candidate ${name} is repeated`)
        }
        seenBallot.add(name)
      }
      ballots.push({ count, names })
      sawBallot = true
    } else {
      throw new ParseError(lineNo, `unknown directive ${directive}`)
    }
  }

  if (!sawCandidates) {
    throw new ParseError(null, 'no candidates')
  }

  return { candidates, ballots }
}
"}

