{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e1-haiku-vs-sonnet-t5/cell-LieiHJ/src/policies.js","content":"/**
 * Runtime state for token buckets and sliding windows, one instance per
 * declared policy, each keeping its own per-key state.
 */

export class TokenBucketPolicy {
  constructor({ name, capacity, refill, per }) {
    this.name = name
    this.capacity = capacity
    this.refill = refill
    this.per = per
    this.cap = capacity * per
    this.states = new Map()
  }

  advance(key, tick) {
    let state = this.states.get(key)
    if (state === undefined) {
      state = { tokens: this.cap, lastTick: tick }
      this.states.set(key, state)
      return
    }
    if (tick > state.lastTick) {
      const delta = tick - state.lastTick
      const added = this.refill * delta
      let tokens = state.tokens + added
      if (tokens > this.cap) tokens = this.cap
      state.tokens = tokens
      state.lastTick = tick
    }
  }

  allow(key) {
    const state = this.states.get(key)
    return state.tokens >= this.per
  }

  record(key) {
    const state = this.states.get(key)
    state.tokens -= this.per
  }
}

export class SlidingWindowPolicy {
  constructor({ name, limit, span }) {
    this.name = name
    this.limit = limit
    this.span = span
    this.states = new Map()
  }

  advance(key, tick) {
    let state = this.states.get(key)
    if (state === undefined) {
      state = { queue: [] }
      this.states.set(key, state)
    }
    const threshold = tick - this.span
    while (state.queue.length > 0 && state.queue[0] <= threshold) {
      state.queue.shift()
    }
  }

  allow(key) {
    const state = this.states.get(key)
    return BigInt(state.queue.length) < this.limit
  }

  record(key) {
    const state = this.states.get(key)
  }
}
"}

