{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e1-haiku-vs-sonnet-t5/cell-LieiHJ/src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js replay` verdicts every event of the limiter
 * file read from standard input, and `node src/cli.js summary` totals the
 * verdicts per key.
 */
import { readFileSync } from 'node:fs'
import { parseLimiterFile } from './parse.js'
import { simulate } from './simulate.js'
import { LineError } from './errors.js'

function main() {
  const mode = process.argv[2]
  if (mode !== 'replay' && mode !== 'summary') {
    process.stderr.write('error: usage: cli.js replay|summary\n')
    process.exit(2)
  }

  const text = readFileSync(0, 'utf8')

  let parsed
  try {
    parsed = parseLimiterFile(text)
  } catch (err) {
    if (err instanceof LineError) {
      process.stderr.write(`error: ${err.message}\n`)
      process.exit(2)
    }
    throw err
  }

  const results = simulate(parsed)

  if (mode === 'replay') {
    let out = ''
    for (const r of results) {
      if (r.allow) {
        out += `${r.tick} ${r.key} allow\n`
      } else {
        out += `${r.tick} ${r.key} deny ${r.deniedBy}\n`
      }
    }
    process.stdout.write(out)
  } else {
    const perKey = new Map()
    let totalAllowed = 0n
    let totalDenied = 0n
    for (const r of results) {
      let counts = perKey.get(r.key)
      if (counts === undefined) {
        counts = { allowed: 0n, denied: 0n }
        perKey.set(r.key, counts)
      }
      if (r.allow) {
        counts.allowed += 1n
        totalAllowed += 1n
      } else {
        counts.denied += 1n
        totalDenied += 1n
      }
    }
    const keys = [...perKey.keys()].sort()
    let out = ''
    for (const key of keys) {
      const c = perKey.get(key)
      out += `${key} allowed=${c.allowed} denied=${c.denied}\n`
    }
    out += `total allowed=${totalAllowed} denied=${totalDenied}\n`
    process.stdout.write(out)
  }

  process.exit(0)
}

main()
"}

