{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e1-haiku-vs-sonnet-t5/cell-MKV75I/src/parse.js","content":"/**
 * Parsing of the election description read from standard input.
 */

const NAME_RE = /^[A-Za-z0-9_-]+$/
const COUNT_RE = /^(0|[1-9][0-9]*)$/

class ParseError extends Error {
  constructor(message, line) {
    super(message)
    this.line = line
  }
}

function fail(message, line) {
  throw new ParseError(message, line)
}

/**
 * Parses the full election text into candidate names and ballots.
 * Throws a ParseError (with a `line` property when applicable) on any
 * failure, matching the messages required by the specification.
 */
export function parseElection(input) {
  const rawLines = input.split('\n')
  if (rawLines.length > 0 && rawLines[rawLines.length - 1] === '') {
    rawLines.pop()
  }

  let candidates = null
  const candidateSet = new Set()
  const ballots = []

  for (let i = 0; i < rawLines.length; i++) {
    const lineNo = i + 1
    const trimmed = rawLines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const tokens = trimmed.split(/\s+/)
    const word = tokens[0]

    if (word === 'candidates') {
      if (candidates !== null) {
        fail('candidates must be declared once, before any ballot', lineNo)
      }
      const names = tokens.slice(1)
      if (names.length === 0) {
        fail('expected candidates <name>...', lineNo)
      }
      for (const name of names) {
        if (!NAME_RE.test(name)) {
          fail(`invalid candidate name ${name}`, lineNo)
        }
        if (candidateSet.has(name)) {
          fail(`candidate ${name} is declared twice`, lineNo)
        }
        candidateSet.add(name)
      }
      candidates = names.slice()
    } else if (word === 'ballot') {
      if (candidates === null) {
        fail('candidates must be declared once, before any ballot', lineNo)
      }
      if (tokens.length < 3) {
        fail('expected ballot <count> <candidate>...', lineNo)
      }
      const countStr = tokens[1]
      if (!COUNT_RE.test(countStr) || countStr === '0') {
        fail('count must be a positive integer', lineNo)
      }
      const count = Number(countStr)
      const names = tokens.slice(2)
      const seen = new Set()
      for (const name of names) {
        if (!candidateSet.has(name)) {
          fail(`unknown candidate ${name}`, lineNo)
        }
        if (seen.has(name)) {
          fail(`candidate ${name} is repeated`, lineNo)
        }
        seen.add(name)
      }
      ballots.push({ count, names })
    } else {
      fail(`unknown directive ${word}`, lineNo)
    }
  }

  if (candidates === null) {
    fail('no candidates', undefined)
  }

  return { candidates, ballots }
}

export { ParseError }
"}

