{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js normalize` normalizes one URI reference per
 * input line; `node src/cli.js resolve` resolves the reference on each line
 * against the base that precedes it. Both print one result per line.
 */

import { readFileSync } from 'fs'

/**
 * Parse a URI reference into its components
 * Returns { scheme, authority, path, query, fragment }
 */
function parseURI(uri) {
  let scheme = null
  let authority = null
  let path = ''
  let query = null
  let fragment = null

  let remaining = uri
  let pos = 0

  // Parse fragment first (from the end)
  const fragmentPos = uri.indexOf('#')
  if (fragmentPos !== -1) {
    fragment = uri.substring(fragmentPos + 1)
    remaining = uri.substring(0, fragmentPos)
  }

  // Parse query
  const queryPos = remaining.indexOf('?')
  if (queryPos !== -1) {
    query = remaining.substring(queryPos + 1)
    remaining = remaining.substring(0, queryPos)
  }

  // Parse scheme: runs to first ':' not preceded by '/', '?', '#'
  let schemeEnd = -1
  for (let i = 0; i < remaining.length; i++) {
    const char = remaining[i]
    if (char === ':') {
      schemeEnd = i
      break
    }
    if (char === '/' || char === '?' || char === '#') {
      break
    }
  }

  if (schemeEnd !== -1) {
    scheme = remaining.substring(0, schemeEnd)
    remaining = remaining.substring(schemeEnd + 1)
  }

  // Parse authority: starts with '//', runs to next '/', '?', '#'
  if (remaining.startsWith('//')) {
    let authorityEnd = -1
    for (let i = 2; i < remaining.length; i++) {
      const char = remaining[i]
      if (char === '/' || char === '?' || char === '#') {
        authorityEnd = i
        break
      }
    }
    if (authorityEnd === -1) {
      authority = remaining.substring(2)
      remaining = ''
    } else {
      authority = remaining.substring(2, authorityEnd)
      remaining = remaining.substring(authorityEnd)
    }
  }

  // Parse path: everything up to '?' or '#'
  let pathEnd = remaining.length
  for (let i = 0; i < remaining.length; i++) {
    if (remaining[i] === '?' || remaining[i] === '#') {
      pathEnd = i
      break
    }
  }
  path = remaining.substring(0, pathEnd)

  return { scheme, authority, path, query, fragment }
}

/**
 * Split authority into userinfo, host, and port
 */
function parseAuthority(authority) {
  if (!authority) {
    return { userinfo: null, host: '', port: null }
  }

  let userinfo = null
  let hostPort = authority

  const lastAtPos = authority.lastIndexOf('@')
  if (lastAtPos !== -1) {
    userinfo = authority.substring(0, lastAtPos)
    hostPort = authority.substring(lastAtPos + 1)
  }

  let host = hostPort
  let port = null

  // Find the first ':' after the last ']' (for IPv6)
  const lastBracketPos = hostPort.lastIndexOf(']')
  const colonPos = hostPort.indexOf(':', lastBracketPos === -1 ? 0 : lastBracketPos + 1)

  if (colonPos !== -1) {
    host = hostPort.substring(0, colonPos)
    port = hostPort.substring(colonPos + 1)
  }

  return { userinfo, host, port }
}

/**
 * Check if a character is unreserved
 */
function isUnreserved(char) {
  const code = char.charCodeAt(0)
  return (code >= 65 && code <= 90) || // A-Z
         (code >= 97 && code <= 122) || // a-z
         (code >= 48 && code <= 57) || // 0-9
         char === '-' || char === '.' || char === '_' || char === '~'
}

/**
 * Normalize percent-encodings in a string
 * Returns { normalized: string, error: null | string }
 */
function normalizePercentEncodings(str, componentName) {
  if (!str) return { normalized: str, error: null }

  let result = ''
  for (let i = 0; i < str.length; i++) {
    if (str[i] === '%') {
      if (i + 2 >= str.length) {
        return { normalized: null, error: `the ${componentName} has a truncated percent-encoding` }
      }
      const hex = str.substring(i + 1, i + 3)
      if (!/^[0-9A-Fa-f]{2}$/.test(hex)) {
        return { normalized: null, error: `the ${componentName} has a truncated percent-encoding` }
      }
      const code = parseInt(hex, 16)
      const char = String.fromCharCode(code)
      if (isUnreserved(char)) {
        result += char
      } else {
        result += '%' + hex.toUpperCase()
      }
      i += 2
    } else {
      result += str[i]
    }
  }
  return { normalized: result, error: null }
}

/**
 * Normalize a URI
 * Returns { normalized: string, error: null | string }
 */
function normalizeURI(uri) {
  const parsed = parseURI(uri)

  // Lowercase scheme
  if (parsed.scheme) {
    parsed.scheme = parsed.scheme.toLowerCase()
  }

  // Normalize percent-encodings in each component
  // Check in order: userinfo, host, path, query, fragment
  const components = ['userinfo', 'host', 'path', 'query', 'fragment']

  if (parsed.authority) {
    const auth = parseAuthority(parsed.authority)
    if (auth.userinfo) {
      const result = normalizePercentEncodings(auth.userinfo, 'userinfo')
      if (result.error) return { normalized: null, error: result.error }
      auth.userinfo = result.normalized
    }
    if (auth.host) {
      const result = normalizePercentEncodings(auth.host, 'host')
      if (result.error) return { normalized: null, error: result.error }
      auth.host = result.normalized
    }
    parsed.authority = rebuildAuthority(auth)
  }

  const pathResult = normalizePercentEncodings(parsed.path, 'path')
  if (pathResult.error) return { normalized: null, error: pathResult.error }
  parsed.path = pathResult.normalized

  if (parsed.query !== null) {
    const queryResult = normalizePercentEncodings(parsed.query, 'query')
    if (queryResult.error) return { normalized: null, error: queryResult.error }
    parsed.query = queryResult.normalized
  }

  if (parsed.fragment !== null) {
    const fragmentResult = normalizePercentEncodings(parsed.fragment, 'fragment')
    if (fragmentResult.error) return { normalized: null, error: fragmentResult.error }
    parsed.fragment = fragmentResult.normalized
  }

  // Lowercase host (already did in userinfo/host normalization above)
  if (parsed.authority) {
    const auth = parseAuthority(parsed.authority)
    auth.host = auth.host.toLowerCase()
    parsed.authority = rebuildAuthority(auth)
  }

  // Drop default ports
  if (parsed.authority) {
    const auth = parseAuthority(parsed.authority)
    if (auth.port) {
      const defaultPorts = { 'http': '80', 'ws': '80', 'https': '443', 'wss': '443', 'ftp': '21' }
      const defaultPort = defaultPorts[parsed.scheme]
      if (auth.port === '' || auth.port === defaultPort) {
        auth.port = null
      }
    }
    parsed.authority = rebuildAuthority(auth)
  }

  // Remove dot segments from path
  parsed.path = removeDotSegments(parsed.path)

  // When authority present and path empty, make path /
  if (parsed.authority && parsed.path === '') {
    parsed.path = '/'
  }

  return { normalized: rebuildURI(parsed), error: null }
}

/**
 * Rebuild authority from components
 */
function rebuildAuthority(auth) {
  let result = ''
  if (auth.userinfo) {
    result += auth.userinfo + '@'
  }
  result += auth.host
  if (auth.port) {
    result += ':' + auth.port
  }
  return result
}

/**
 * Rebuild URI from components
 */
function rebuildURI(parsed) {
  let result = ''
  if (parsed.scheme) {
    result += parsed.scheme + ':'
  }
  if (parsed.authority) {
    result += '//' + parsed.authority
  }
  result += parsed.path
  if (parsed.query !== null) {
    result += '?' + parsed.query
  }
  if (parsed.fragment !== null) {
    result += '#' + parsed.fragment
  }
  return result
}

/**
 * Remove dot segments from path according to RFC 3986 section 5.2.4
 */
function removeDotSegments(path) {
  if (!path) return path

  const input = path.split('/')
  const output = []

  for (let i = 0; i < input.length; i++) {
    const segment = input[i]

    if (segment === '' || segment === '.') {
      // A '.' or empty segment at the end: drop it
      if (i === input.length - 1 && segment === '.') {
        // Keep the trailing empty segment for paths like "foo/."
        if (i > 0) {
          output.push('')
        }
      }
      // Otherwise just skip it
    } else if (segment === '..') {
      // A '..' segment removes the segment before it
      if (output.length > 0) {
        // Don't remove the first empty segment (root)
        if (!(output.length === 1 && output[0] === '')) {
          output.pop()
        }
      }
      // If this is the last segment, keep trailing empty
      if (i === input.length - 1) {
        output.push('')
      }
    } else {
      output.push(segment)
    }
  }

  return output.join('/')
}

/**
 * Merge a reference path onto a base path
 */
function mergePaths(basePath, baseAuthority, refPath) {
  if (baseAuthority && basePath === '') {
    // Base has authority and empty path: prepend /
    return '/' + refPath
  }
  // Keep everything of base up to and including last /
  const lastSlash = basePath.lastIndexOf('/')
  if (lastSlash !== -1) {
    return basePath.substring(0, lastSlash + 1) + refPath
  }
  return refPath
}

/**
 * Resolve a reference against a base
 * Returns { resolved: string, error: null | string }
 */
function resolveReference(base, reference) {
  const baseParsed = parseURI(base)
  const refParsed = parseURI(reference)

  let targetScheme = baseParsed.scheme
  let targetAuthority = baseParsed.authority
  let targetPath = baseParsed.path
  let targetQuery = baseParsed.query
  let targetFragment = refParsed.fragment

  if (refParsed.scheme) {
    // Reference has a scheme: use reference as-is (just normalize path)
    targetScheme = refParsed.scheme
    targetAuthority = refParsed.authority
    targetPath = removeDotSegments(refParsed.path)
    targetQuery = refParsed.query
  } else {
    if (refParsed.authority) {
      // Reference has authority: use it
      targetAuthority = refParsed.authority
      targetPath = removeDotSegments(refParsed.path)
      targetQuery = refParsed.query
    } else {
      if (refParsed.path === '') {
        // Reference has empty path
        targetPath = baseParsed.path
        if (refParsed.query !== null) {
          targetQuery = refParsed.query
        }
        // else keep base query
      } else {
        // Reference has a path
        if (refParsed.path.startsWith('/')) {
          // Absolute path in reference
          targetPath = removeDotSegments(refParsed.path)
        } else {
          // Relative path: merge
          targetPath = mergePaths(baseParsed.path, baseParsed.authority, refParsed.path)
          targetPath = removeDotSegments(targetPath)
        }
        targetQuery = refParsed.query
      }
      targetAuthority = baseParsed.authority
    }
    targetScheme = baseParsed.scheme
  }

  // When authority present and path empty, make path /
  if (targetAuthority && targetPath === '') {
    targetPath = '/'
  }

  const result = rebuildURI({
    scheme: targetScheme,
    authority: targetAuthority,
    path: targetPath,
    query: targetQuery,
    fragment: targetFragment
  })

  // Normalize the resolved URI
  return normalizeURI(result)
}

/**
 * Main function
 */
function main() {
  const args = process.argv.slice(2)

  if (args.length !== 1 || (args[0] !== 'normalize' && args[0] !== 'resolve')) {
    process.stderr.write('error: usage: cli.js normalize|resolve\n')
    process.exit(2)
  }

  const mode = args[0]
  const input = readFileSync(0, 'utf8')
  const lines = input.split('\n')

  // Drop empty tail from trailing newline
  if (lines.length > 0 && lines[lines.length - 1] === '') {
    lines.pop()
  }

  let lineNum = 0
  for (const line of lines) {
    lineNum++

    if (mode === 'normalize') {
      const result = normalizeURI(line)
      if (result.error) {
        process.stderr.write(`error: line ${lineNum}: ${result.error}\n`)
        process.exit(2)
      }
      process.stdout.write(result.normalized + '\n')
    } else {
      // resolve mode
      const spacePos = line.indexOf(' ')
      if (spacePos === -1) {
        process.stderr.write(`error: line ${lineNum}: expected a base and a reference\n`)
        process.exit(2)
      }

      const base = line.substring(0, spacePos)
      const reference = line.substring(spacePos + 1)

      // Check that base has a scheme
      const baseParsed = parseURI(base)
      if (!baseParsed.scheme) {
