// Skip spaces/tabs; if what follows (after skipping) is a comment starter (# or ;)
// outside of a quoted string, treat the remainder of the line as consumed.
function skipWS(line, pos) {
  while (pos < line.length && (line[pos] === ' ' || line[pos] === '\t')) pos++
