      continue
    }
    break
  }
  return { names, pos }
}

const INT_RE = /^[+-]?\d+(_\d+)*$/
const FLOAT_RE = /^[+-]?\d+(_\d+)*(\.\d+(_\d+)*)?([eE][+-]?\d+(_\d+)*)?$/

function parseIntUnderscored(token) {
  let sign = 1n
  let s = token
  if (s[0] === '+') s = s.slice(1)
  else if (s[0] === '-') { sign = -1n; s = s.slice(1) }
  s = s.replace(/_/g, '')
  return sign * BigInt(s)
}

function parseValue(line, pos, lineNo, path) {
  pos = skipWS(line, pos)
  if (pos >= line.length) fail(lineNo, 'expected a value')
  const c = line[pos]
  if (c === '"') {
    const r = parseBasicString(line, pos, lineNo)
    return { node: { type: 'string', value: r.text }, pos: r.pos }
  }
  if (c === "'") {
    const r = parseLiteralString(line, pos, lineNo)
    return { node: { type: 'string', value: r.text }, pos: r.pos }
  }
  if (c === ',' || c === ']' || c === '}') fail(lineNo, 'expected a value')
  if (c === '[') return parseArray(line, pos, lineNo, path)
  if (c === '{') return parseInlineTable(line, pos, lineNo, path)

  let p = pos
  while (p < line.length && !(line[p] === ' ' || line[p] === '\t' || line[p] === ',' || line[p] === ']' || line[p] === '}')) p++
  const token = line.slice(pos, p)
  if (token === 'true') return { node: { type: 'boolean', value: true }, pos: p }
  if (token === 'false') return { node: { type: 'boolean', value: false }, pos: p }
  if (INT_RE.test(token)) {
    return { node: { type: 'integer', value: parseIntUnderscored(token) }, pos: p }
  }
  if (FLOAT_RE.test(token) && (token.includes('.') || /[eE]/.test(token))) {
    return { node: { type: 'float', value: parseFloat(token.replace(/_/g, '')) }, pos: p }
  }
  fail(lineNo, 'invalid value ' + token)
}

function parseArray(line, pos, lineNo, path) {
  pos = pos + 1 // consume '['
  const items = []
  let p = skipWS(line, pos)
  if (p < line.length && line[p] === ']') return { node: { type: 'array', items }, pos: p + 1 }
  pos = p
  while (true) {
    const r = parseValue(line, pos, lineNo, path)
    items.push(r.node)
    pos = skipWS(line, r.pos)
    if (pos >= line.length) fail(lineNo, 'unterminated array')
    if (line[pos] === ',') {
      pos = pos + 1
      const p2 = skipWS(line, pos)
      if (p2 < line.length && line[p2] === ']') { pos = p2 + 1; break }
      pos = p2
      continue
    } else if (line[pos] === ']') {
      pos = pos + 1
      break
    } else {
      fail(lineNo, 'unterminated array')
    }
  }
  return { node: { type: 'array', items }, pos }
}

function parseInlineTable(line, pos, lineNo, path) {
  pos = pos + 1 // consume '{'
  const table = { type: 'table', entries: new Map(), headerDefined: false }
  let p = skipWS(line, pos)
  if (p < line.length && line[p] === '}') return { node: table, pos: p + 1 }
  pos = p
  while (true) {
    const nameRes = parseDottedName(line, pos, lineNo)
    pos = skipWS(line, nameRes.pos)
    if (pos >= line.length || line[pos] !== '=') fail(lineNo, 'expected = in an inline table')
    pos = pos + 1
    const childPath = path.concat(nameRes.names.map((n) => n.text))
    const vRes = parseValue(line, pos, lineNo, childPath)
    pos = vRes.pos
    assignInto(table, nameRes.names, vRes.node, path, lineNo)
    pos = skipWS(line, pos)
    if (pos >= line.length) fail(lineNo, 'unterminated inline table')
    if (line[pos] === ',') {
      pos = pos + 1
      pos = skipWS(line, pos)
      continue
    } else if (line[pos] === '}') {
      pos = pos + 1
      break
    } else {
      fail(lineNo, 'unterminated inline table')
    }
  }
  return { node: table, pos }
}

function assignInto(tableNode, names, valueNode, pathPrefix, lineNo) {
  let current = tableNode
  const path = pathPrefix.slice()
  for (let i = 0; i < names.length - 1; i++) {
    const seg = names[i].text
    path.push(seg)
    let node = current.entries.get(seg)
    if (!node) {
      node = { type: 'table', entries: new Map(), headerDefined: false }
      current.entries.set(seg, node)
    } else if (node.type === 'table') {
      // walk into it
    } else if (node.type === 'arraytable') {
      node = node.items[node.items.length - 1]
    } else {
      fail(lineNo, path.join('.') + ' is not a table')
    }
    current = node
  }
  const last = names[names.length - 1].text
  path.push(last)
  if (current.entries.has(last)) fail(lineNo, 'key ' + path.join('.') + ' is defined twice')
  current.entries.set(last, valueNode)
}

