  let current = root
  const path = []
  for (let i = 0; i < names.length - 1; i++) {
    const seg = names[i].text
    path.push(seg)
    let node = current.entries.get(seg)
    if (!node) {
      node = { type: 'table', entries: new Map(), headerDefined: false }
      current.entries.set(seg, node)
    } else if (node.type === 'table') {
      // use it
    } else if (node.type === 'arraytable') {
      node = node.items[node.items.length - 1]
    } else {
      fail(lineNo, path.join('.') + ' is not a table')
    }
    current = node
  }
  const last = names[names.length - 1].text
  path.push(last)
  const fullPath = path.join('.')
  const existing = current.entries.get(last)
  if (isArray) {
    let arrNode
    if (!existing) {
      arrNode = { type: 'arraytable', items: [] }
      current.entries.set(last, arrNode)
    } else if (existing.type === 'arraytable') {
      arrNode = existing
    } else {
      fail(lineNo, fullPath + ' is not an array of tables')
    }
    const newTable = { type: 'table', entries: new Map(), headerDefined: true }
    arrNode.items.push(newTable)
    return { table: newTable, path }
  } else {
    let tbl
    if (!existing) {
      tbl = { type: 'table', entries: new Map(), headerDefined: true }
      current.entries.set(last, tbl)
    } else if (existing.type === 'table') {
      if (existing.headerDefined) fail(lineNo, 'table ' + fullPath + ' is defined twice')
      existing.headerDefined = true
      tbl = existing
    } else {
      fail(lineNo, fullPath + ' is not a table')
    }
    return { table: tbl, path }
  }
}

export function parseDocument(input) {
  const lines = input.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()

  const root = { type: 'table', entries: new Map(), headerDefined: true }
  let currentTable = root
  let currentPath = []

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const line = lines[i]
    let pos = skipWS(line, 0)
    if (pos >= line.length) continue // blank or comment-only line

    if (line[pos] === '[') {
      pos = pos + 1
      let isArray = false
      if (line[pos] === '[') { isArray = true; pos = pos + 1 }
      const nameRes = parseDottedName(line, pos, lineNo)
      pos = skipWS(line, nameRes.pos)
      if (isArray) {
        if (line[pos] === ']' && line[pos + 1] === ']') pos = pos + 2
        else fail(lineNo, 'unterminated table header')
      } else {
        if (line[pos] === ']') pos = pos + 1
        else fail(lineNo, 'unterminated table header')
      }
      pos = skipWS(line, pos)
      if (pos < line.length) fail(lineNo, 'trailing text after a table header')
      const res = applyHeader(root, nameRes.names, isArray, lineNo)
      currentTable = res.table
      currentPath = res.path
    } else {
      const nameRes = parseDottedName(line, pos, lineNo)
      pos = skipWS(line, nameRes.pos)
      if (pos >= line.length || line[pos] !== '=') fail(lineNo, 'expected key = value')
      pos = pos + 1
      const childPath = currentPath.concat(nameRes.names.map((n) => n.text))
      const vRes = parseValue(line, pos, lineNo, childPath)
      pos = skipWS(line, vRes.pos)
      if (pos < line.length) fail(lineNo, 'trailing text after a value')
      assignInto(currentTable, nameRes.names, vRes.node, currentPath, lineNo)
    }
  }

  return root
}
"}

