    case 'array':
    case 'arraytable': {
      const items = node.items
      if (items.length === 0) return '[]'
      const parts = items.map((it) => padIn + stringifyValue(it, indentLevel + 1))
      return '[\n' + parts.join(',\n') + '\n' + pad + ']'
    }
