  switch (node.type) {
    case 'table':
      return 'table'
    case 'array':
    case 'arraytable':
      return 'array'
    default:
      return node.type
  }
}

function walk(node, path, lines) {
  if (node.type === 'table') {
    const keys = sortedKeys(node)
    for (const k of keys) {
      const child = node.entries.get(k)
      const childPath = path ? path + '.' + k : k
      lines.push(childPath + ' ' + typeName(child))
      walk(child, childPath, lines)
    }
