{"file_path":"src/formatter.js","content":"export function formatJson(obj) {
  return JSON.stringify(obj, null, 2) + '\n'
}

export function formatKeys(obj, prefix = '') {
  const lines = []

  // Collect all keys and sort them
  const keys = Object.keys(obj).sort()

  for (const key of keys) {
    const value = obj[key]
    const path = prefix ? `${prefix}.${key}` : key

    if (Array.isArray(value)) {
      // Array of tables
      lines.push(`${path} array`)
      for (let i = 0; i < value.length; i++) {
        const table = value[i]
        if (typeof table === 'object' && table !== null) {
          const subLines = formatKeys(table, `${path}[${i}]`)
          lines.push(...subLines.split('\n').filter(l => l))
        }
      }
    } else if (typeof value === 'object' && value !== null) {
      // Table
      lines.push(`${path} table`)
      const subLines = formatKeys(value, path)
      lines.push(...subLines.split('\n').filter(l => l))
    } else if (typeof value === 'string') {
      lines.push(`${path} string`)
    } else if (typeof value === 'boolean') {
      lines.push(`${path} boolean`)
    } else if (Number.isInteger(value)) {
      lines.push(`${path} integer`)
    } else if (typeof value === 'number') {
      lines.push(`${path} float`)
    }
  }

  return lines.join('\n')
}
"}

