  return JSON.stringify(obj, null, 2) + '\n'
}","new_string":"export function formatJson(obj) {
  return stringifyWithSortedKeys(obj, 0) + '\n'
}

function stringifyWithSortedKeys(value, depth) {
  const indent = '  '.repeat(depth)
  const nextIndent = '  '.repeat(depth + 1)

  if (value === null) {
    return 'null'
  }

  if (typeof value === 'string') {
    return JSON.stringify(value)
  }

  if (typeof value === 'number' || typeof value === 'boolean') {
    return String(value)
  }

  if (Array.isArray(value)) {
    if (value.length === 0) {
      return '[]'
    }
    const items = value.map(item => nextIndent + stringifyWithSortedKeys(item, depth + 1))
    return '[\n' + items.join(',\n') + '\n' + indent + ']'
  }

  if (typeof value === 'object') {
    const keys = Object.keys(value).sort()
    if (keys.length === 0) {
      return '{}'
    }
    const items = keys.map(key => nextIndent + JSON.stringify(key) + ': ' + stringifyWithSortedKeys(value[key], depth + 1))
    return '{\n' + items.join(',\n') + '\n' + indent + '}'
  }

  return String(value)
}"}

