 * Token bucket and sliding window policy state, keyed independently per
 * limiter key.
 */

export function createBucketPolicy(capacity, refill, per) {
  const cap = capacity * per
  const states = new Map()
  return {
    type: 'bucket',
    advance(key, tick) {
      let state = states.get(key)
      if (!state) {
        state = { tokensNum: cap, lastTick: tick }
        states.set(key, state)
        return
      }
      const n = tick - state.lastTick
      if (n > 0n) {
        let next = state.tokensNum + refill * n
        if (next > cap) next = cap
        state.tokensNum = next
        state.lastTick = tick
      }
    },
    allows(key) {
      const state = states.get(key)
      return state.tokensNum >= per
    },
    record(key) {
      const state = states.get(key)
      state.tokensNum -= per
    },
  }
}

export function createWindowPolicy(limit, span) {
  const states = new Map()
  return {
    type: 'window',
    advance(key, tick) {
      let state = states.get(key)
      if (!state) {
        state = { ticks: [] }
        states.set(key, state)
      }
      const threshold = tick - span
      while (state.ticks.length > 0 && state.ticks[0] <= threshold) {
        state.ticks.shift()
      }
    },
    allows(key) {
      const state = states.get(key)
      return BigInt(state.ticks.length) < limit
    },
    record(key, tick) {
      const state = states.get(key)
      state.ticks.push(tick)
    },
  }
}
"}

