content.arguments:
{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e1-haiku-vs-sonnet-t5/cell-RA0MYh/src/pack.js","content":"// Worker-limited simulation for the `pack` mode.

/**
 * Simulates the graph on `workerCount` workers, greedily starting the
 * highest-priority ready task (ties broken by ascending name) on the
 * lowest-index free worker whenever both are available at the current
 * instant, then jumping time forward to the next worker-free instant.
 * Returns { assignments, makespan } where assignments is an array (one
 * entry per worker) of { name, start, finish } objects in run order.
 */
export function pack(tasks, deps, priority, workerCount) {
  const names = [...tasks.keys()].sort()
  const finishTime = new Map()
  const assigned = new Set()
  const workerBusyUntil = new Array(workerCount).fill(0)
  const assignments = Array.from({ length: workerCount }, () => [])

  const total = names.length
  let doneCount = 0
  let time = 0

  function isReady(name) {
    const dependencies = deps.get(name) || []
    for (const dep of dependencies) {
      const f = finishTime.get(dep)
      if (f === undefined || f > time) return false
    }
    return true
  }

  while (doneCount < total) {
    // Repeatedly assign while a worker is free and a task is ready.
    for (;;) {
      let workerIdx = -1
      for (let i = 0; i < workerCount; i++) {
        if (workerBusyUntil[i] <= time) {
          workerIdx = i
          break
        }
      }
      if (workerIdx === -1) break

      let best = null
      for (const name of names) {
        if (assigned.has(name)) continue
        if (!isReady(name)) continue
        if (
          best === null ||
          priority.get(name) > priority.get(best) ||
          (priority.get(name) === priority.get(best) && name < best)
        ) {
          best = name
        }
      }
      if (best === null) break

      const cost = tasks.get(best)
      const startT = time
      const endT = time + cost
      assigned.add(best)
      finishTime.set(best, endT)
      workerBusyUntil[workerIdx] = endT
      assignments[workerIdx].push({ name: best, start: startT, finish: endT })
      doneCount++
    }

    if (doneCount >= total) break

    let next = Infinity
    for (let i = 0; i < workerCount; i++) {
      if (workerBusyUntil[i] > time) next = Math.min(next, workerBusyUntil[i])
    }
    if (next === Infinity) {
      // Should not happen for an acyclic graph; guard against an infinite loop.
      break
    }
    time = next
  }

  let makespan = 0
  for (const f of finishTime.values()) makespan = Math.max(makespan, f)

  return { assignments, makespan }
}
"}

