{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js merge`, `node src/cli.js merge2` and
 * `node src/cli.js regions` each read three documents from standard input and
 * report the three-way merge of the second into the first and the third.
 */

import { computeRegions } from './merge.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function splitInput(input) {
  let lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const parts = [[]]
  for (const line of lines) {
    if (line === '%%%') {
      parts.push([])
    } else {
      parts[parts.length - 1].push(line)
    }
  }
  return parts
}

function readStdin() {
  const fs = require('fs')
  return fs.readFileSync(0, 'utf8')
}

function main() {
  const mode = process.argv[2]
  if (mode !== 'merge' && mode !== 'merge2' && mode !== 'regions') {
    fail('usage: cli.js merge|merge2|regions')
    return
  }

  const input = readStdinSync()
  const parts = splitInput(input)
  if (parts.length !== 3) {
    fail('expected three parts separated by %%%')
    return
  }

  const [mine, base, theirs] = parts
  const regions = computeRegions(mine, base, theirs)

  let conflict = false
  const out = []

  if (mode === 'regions') {
    for (const region of regions) {
      if (region.type === 'stable' || region.type === 'mine' || region.type === 'theirs' || region.type === 'both') {
        out.push(`${region.type} ${region.lines.length}\n`)
      } else {
        conflict = true
        out.push(`conflict mine=${region.mine.length} base=${region.base.length} theirs=${region.theirs.length}\n`)
      }
    }
  } else {
    const includeBase = mode === 'merge'
    for (const region of regions) {
      if (region.type === 'conflict') {
        conflict = true
        out.push('<<<<<<< mine\n')
        for (const l of region.mine) out.push(`${l}\n`)
        if (includeBase) {
          out.push('||||||| base\n')
          for (const l of region.base) out.push(`${l}\n`)
        }
        out.push('=======\n')
        for (const l of region.theirs) out.push(`${l}\n`)
        out.push('>>>>>>> theirs\n')
      } else {
        for (const l of region.lines) out.push(`${l}\n`)
      }
    }
  }

  process.stdout.write(out.join(''))
  process.exit(conflict ? 1 : 0)
}

function readStdinSync() {
  const fs = require('fs')
  return fs.readFileSync(0, 'utf8')
}

main()
"}

