/**
 * URI normalization and resolution program
 * Implements RFC 3986 parsing, normalization, and resolution
 */

/**
 * Parses a URI reference into its components
 * @param {string} uri - The URI reference to parse
 * @returns {object} - Object with scheme, authority, path, query, fragment, and component presence flags
 */
function parseUri(uri) {
  let pos = 0;
  let scheme = null;
  let authority = null;
  let path = '';
  let query = null;
  let fragment = null;

  // Parse scheme: optional scheme running to first ':', not preceded by '/', '?', or '#'
  const schemeEnd = uri.search(/[:/?#]/);
  if (schemeEnd !== -1 && uri[schemeEnd] === ':') {
    // Check if there's a '/', '?', or '#' before the ':'
    if (uri.substring(0, schemeEnd).search(/[/?#]/) === -1) {
      scheme = uri.substring(0, schemeEnd);
      pos = schemeEnd + 1;
    }
  }

  // Parse authority: introduced by '//' and running to next '/', '?', or '#'
  if (uri.substring(pos, pos + 2) === '//') {
    pos += 2;
    const remaining = uri.substring(pos);
    const authorityEnd = remaining.search(/[/?#]/);
    if (authorityEnd === -1) {
      authority = remaining;
      pos = uri.length;
    } else {
      authority = remaining.substring(0, authorityEnd);
      pos += authorityEnd;
    }
  }

  // Parse path: up to next '?' or '#'
  const remaining = uri.substring(pos);
  const queryOrFragmentStart = remaining.search(/[?#]/);
  if (queryOrFragmentStart === -1) {
    path = remaining;
    pos = uri.length;
  } else {
    path = remaining.substring(0, queryOrFragmentStart);
    pos += queryOrFragmentStart;
  }

  // Parse query: from '?' to next '#'
  if (pos < uri.length && uri[pos] === '?') {
    pos++;
    const remaining = uri.substring(pos);
    const fragmentStart = remaining.indexOf('#');
    if (fragmentStart === -1) {
      query = remaining;
      pos = uri.length;
    } else {
      query = remaining.substring(0, fragmentStart);
      pos += fragmentStart;
    }
  }

  // Parse fragment: from '#' to end
  if (pos < uri.length && uri[pos] === '#') {
    pos++;
    fragment = uri.substring(pos);
  }

  return { scheme, authority, path, query, fragment };
}

/**
 * Parses an authority into userinfo, host, and port
 * @param {string} authority - The authority component
 * @returns {object} - Object with userinfo, host, port
 */
function parseAuthority(authority) {
  let userinfo = null;
  let host = '';
  let port = null;

  // Parse userinfo: everything before the last '@'
  const lastAtIndex = authority.lastIndexOf('@');
  if (lastAtIndex !== -1) {
    userinfo = authority.substring(0, lastAtIndex);
    authority = authority.substring(lastAtIndex + 1);
  }

  // Parse port: everything after the first ':' that follows the last ']'
  const lastBracketIndex = authority.lastIndexOf(']');
  const colonIndex = authority.indexOf(':', lastBracketIndex + 1);
  if (colonIndex !== -1) {
    host = authority.substring(0, colonIndex);
    port = authority.substring(colonIndex + 1);
  } else {
    host = authority;
  }

  return { userinfo, host, port };
}

/**
 * Reconstructs authority from its parts
 */
function reconstructAuthority(userinfo, host, port) {
  let result = '';
  if (userinfo !== null) {
    result += userinfo + '@';
  }
  result += host;
  if (port !== null) {
    result += ':' + port;
  }
  return result;
}

/**
 * Checks if a character is unreserved
 */
function isUnreserved(char) {
  const code = char.charCodeAt(0);
  return (code >= 65 && code <= 90) || // A-Z
         (code >= 97 && code <= 122) || // a-z
         (code >= 48 && code <= 57) || // 0-9
         char === '-' || char === '.' || char === '_' || char === '~';
}

/**
 * Normalizes percent-encodings in a component
 * Returns null if there's a truncated percent-encoding
 */
function normalizePercentEncoding(component) {
  if (component === null) return null;

  let result = '';
  for (let i = 0; i < component.length; i++) {
    if (component[i] === '%') {
      if (i + 2 >= component.length) {
        return null; // Truncated
      }
      const hex = component.substring(i + 1, i + 3);
      if (!/^[0-9A-Fa-f]{2}$/.test(hex)) {
        return null; // Invalid hex
      }
      const char = String.fromCharCode(parseInt(hex, 16));
      if (isUnreserved(char)) {
        result += char;
      } else {
        result += '%' + hex.toUpperCase();
      }
      i += 2;
    } else {
      result += component[i];
    }
  }
  return result;
}

/**
 * Removes dot segments from a path
 */
function removeDotSegments(path) {
  // Algorithm from RFC 3986 Section 5.2.4
  let inputBuffer = path;
  let outputBuffer = '';

  while (inputBuffer.length > 0) {
    // A: If input buffer begins with "../" or "./"
    if (inputBuffer.startsWith('../')) {
      inputBuffer = inputBuffer.substring(3);
    } else if (inputBuffer.startsWith('./')) {
      inputBuffer = inputBuffer.substring(2);
    }
    // B: If input buffer begins with "/./"
    else if (inputBuffer.startsWith('/./')) {
      inputBuffer = '/' + inputBuffer.substring(3);
    } else if (inputBuffer === '/.') {
      inputBuffer = '/';
    }
    // C: If input buffer begins with "/../"
    else if (inputBuffer.startsWith('/../')) {
      inputBuffer = '/' + inputBuffer.substring(4);
      const lastSlash = outputBuffer.lastIndexOf('/');
      if (lastSlash !== -1) {
        outputBuffer = outputBuffer.substring(0, lastSlash);
      }
    } else if (inputBuffer === '/..') {
      inputBuffer = '/';
      const lastSlash = outputBuffer.lastIndexOf('/');
      if (lastSlash !== -1) {
        outputBuffer = outputBuffer.substring(0, lastSlash);
      }
    }
    // D: If input buffer consists only of "." or ".."
    else if (inputBuffer === '.' || inputBuffer === '..') {
      inputBuffer = '';
    }
    // E: Move first path segment to output
    else {
      let segmentEnd;
      if (inputBuffer.startsWith('/')) {
        segmentEnd = inputBuffer.indexOf('/', 1);
        if (segmentEnd === -1) {
          segmentEnd = inputBuffer.length;
        }
      } else {
        segmentEnd = inputBuffer.indexOf('/');
        if (segmentEnd === -1) {
          segmentEnd = inputBuffer.length;
        }
      }
      outputBuffer += inputBuffer.substring(0, segmentEnd);
      inputBuffer = inputBuffer.substring(segmentEnd);
    }
  }

  return outputBuffer;
}

/**
 * Normalizes a URI
 */
function normalizeUri(parsed) {
  // 1. Lowercase scheme (ASCII only)
  if (parsed.scheme !== null) {
    parsed.scheme = parsed.scheme.toLowerCase();
  }

  // 2. Normalize percent-encodings in every component
  // Check in order: userinfo, host, query, fragment, path
  let authorityObj = null;
  if (parsed.authority !== null) {
    authorityObj = parseAuthority(parsed.authority);
  }

  if (authorityObj && authorityObj.userinfo !== null) {
    const normalized = normalizePercentEncoding(authorityObj.userinfo);
    if (normalized === null) {
      return { error: 'userinfo' };
    }
    authorityObj.userinfo = normalized;
  }

  if (authorityObj) {
    const normalized = normalizePercentEncoding(authorityObj.host);
    if (normalized === null) {
      return { error: 'host' };
    }
    authorityObj.host = normalized;
  }

  // 3. Lowercase the host (ASCII only)
  if (authorityObj) {
    authorityObj.host = authorityObj.host.toLowerCase();
  }

  // 4. Drop the port if empty or default for the scheme
  if (authorityObj && authorityObj.port !== null) {
    const defaultPorts = { 'http': '80', 'ws': '80', 'https': '443', 'wss': '443', 'ftp': '21' };
    const defaultPort = defaultPorts[parsed.scheme];
    if (authorityObj.port === '' || authorityObj.port === defaultPort) {
      authorityObj.port = null;
    }
  }

  if (authorityObj) {
    parsed.authority = reconstructAuthority(authorityObj.userinfo, authorityObj.host, authorityObj.port);
  }

  // Normalize percent-encodings in query and fragment
  if (parsed.query !== null) {
    const normalized = normalizePercentEncoding(parsed.query);
    if (normalized === null) {
      return { error: 'query' };
    }
    parsed.query = normalized;
  }

  if (parsed.fragment !== null) {
    const normalized = normalizePercentEncoding(parsed.fragment);
    if (normalized === null) {
      return { error: 'fragment' };
    }
    parsed.fragment = normalized;
  }

  // Normalize percent-encodings in path
  const normalized = normalizePercentEncoding(parsed.path);
  if (normalized === null) {
    return { error: 'path' };
  }
  parsed.path = normalized;

  // Remove dot segments from the path
  parsed.path = removeDotSegments(parsed.path);

  // If authority is present and path is empty, make path '/'
  if (parsed.authority !== null && parsed.path === '') {
    parsed.path = '/';
  }

  return parsed;
}

/**
 * Reconstructs a URI from its components
 */
function reconstructUri(parsed) {
  let result = '';
  if (parsed.scheme !== null) {
    result += parsed.scheme + ':';
  }
  if (parsed.authority !== null) {
    result += '//' + parsed.authority;
  }
  result += parsed.path;
  if (parsed.query !== null) {
    result += '?' + parsed.query;
  }
  if (parsed.fragment !== null) {
    result += '#' + parsed.fragment;
  }
  return result;
}

/**
 * Merges a relative path with a base path
 */
function mergePaths(baseParsed, referencePath) {
  if (baseParsed.authority !== null && baseParsed.path === '') {
    // Base has authority and empty path
    return '/' + referencePath;
  } else {
    // Keep everything up to and including the last '/' in base path
    const lastSlash = baseParsed.path.lastIndexOf('/');
    if (lastSlash !== -1) {
      return baseParsed.path.substring(0, lastSlash + 1) + referencePath;
    } else {
      return referencePath;
    }
  }
}

/**
 * Resolves a reference URI against a base URI
 */
function resolveUri(baseParsed, referenceParsed) {
  let target = {};

  if (referenceParsed.scheme !== null) {
    // Reference has a scheme - it's the target
    target.scheme = referenceParsed.scheme;
    target.authority = referenceParsed.authority;
    target.path = removeDotSegments(referenceParsed.path);
    target.query = referenceParsed.query;
  } else {
    if (referenceParsed.authority !== null) {
      // Reference has authority
      target.authority = referenceParsed.authority;
      target.path = removeDotSegments(referenceParsed.path);
      target.query = referenceParsed.query;
    } else {
      if (referenceParsed.path === '') {
        // Reference has empty path
        target.path = baseParsed.path;
        if (referenceParsed.query !== null) {
          target.query = referenceParsed.query;
        } else {
          target.query = baseParsed.query;
        }
      } else {
        if (referenceParsed.path.startsWith('/')) {
          // Reference path starts with '/'
          target.path = removeDotSegments(referenceParsed.path);
        } else {
          // Merge paths
          target.path = mergePaths(baseParsed, referenceParsed.path);
          target.path = removeDotSegments(target.path);
        }
        target.query = referenceParsed.query;
      }
      target.authority = baseParsed.authority;
    }
    target.scheme = baseParsed.scheme;
  }

  target.fragment = referenceParsed.fragment;

  return target;
}

/**
 * Main CLI logic
 */
async function main() {
  const args = process.argv.slice(2);

  if (args.length !== 1 || (args[0] !== 'normalize' && args[0] !== 'resolve')) {
    process.stderr.write('error: usage: cli.js normalize|resolve\n');
    process.exit(2);
  }

  const mode = args[0];

  // Read all input
  let input = '';
  for await (const chunk of process.stdin) {
    input += chunk;
  }

  // Split on newlines and drop empty tail
  let lines = input.split('\n');
  if (lines.length > 0 && lines[lines.length - 1] === '') {
    lines.pop();
  }

  // Process each line
  for (let i = 0; i < lines.length; i++) {
    const lineNum = i + 1;
    const line = lines[i];

    try {
      if (mode === 'normalize') {
        const parsed = parseUri(line);
        const normalized = normalizeUri(parsed);
        if (normalized.error) {
          process.stderr.write(`error: line ${lineNum}: the ${normalized.error} has a truncated percent-encoding\n`);
          process.exit(2);
        }
        const result = reconstructUri(normalized);
        process.stdout.write(result + '\n');
      } else {
        // resolve mode
        const spaceIndex = line.indexOf(' ');
        if (spaceIndex === -1) {
          process.stderr.write(`error: line ${lineNum}: expected a base and a reference\n`);
          process.exit(2);
        }

        const baseStr = line.substring(0, spaceIndex);
        const referenceStr = line.substring(spaceIndex + 1);

        const baseParsed = parseUri(baseStr);
        if (baseParsed.scheme === null) {
          process.stderr.write(`error: line ${lineNum}: the base has no scheme\n`);
          process.exit(2);
        }

        // Normalize the base first
        let normalizedBase = normalizeUri(baseParsed);
        if (normalizedBase.error) {
          process.stderr.write(`error: line ${lineNum}: the ${normalizedBase.error} has a truncated percent-encoding\n`);
          process.exit(2);
        }

        const referenceParsed = parseUri(referenceStr);

        // Resolve
        const resolved = resolveUri(normalizedBase, referenceParsed);

        // Normalize the result
        let normalized = normalizeUri(resolved);
        if (normalized.error) {
          process.stderr.write(`error: line ${lineNum}: the ${normalized.error} has a truncated percent-encoding\n`);
          process.exit(2);
        }

        const result = reconstructUri(normalized);
        process.stdout.write(result + '\n');
      }
    } catch (err) {
      process.stderr.write(`error: line ${lineNum}: ${err.message}\n`);
      process.exit(2);
    }
  }

  process.exit(0);
}

main().catch(err => {
  process.stderr.write(`error: ${err.message}\n`);
  process.exit(2);
});
"}

