export function parseAuthority(authority) {
  let userinfo
  let rem = authority
  const atIdx = authority.lastIndexOf('@')
  if (atIdx !== -1) {
    userinfo = authority.slice(0, atIdx)
    rem = authority.slice(atIdx + 1)
  }

  const bracketIdx = rem.lastIndexOf(']')
  const searchFrom = bracketIdx === -1 ? 0 : bracketIdx + 1
  const colonIdx = rem.indexOf(':', searchFrom)

  let host, port
  if (colonIdx === -1) {
    host = rem
  } else {
    host = rem.slice(0, colonIdx)
    port = rem.slice(colonIdx + 1)
  }

  return { userinfo, host, port }
}

function asciiLower(s) {
  let out = ''
  for (const ch of s) {
    const code = ch.codePointAt(0)
    if (code >= 0x41 && code <= 0x5a) {
      out += String.fromCharCode(code + 0x20)
    } else {
      out += ch
    }
  }
