 * character it represents is unreserved. Throws a `UriError` naming
 * `name` when a `%` is not followed by two hex digits.
 */
function normalizePercent(str, name) {
  let out = ''
  let i = 0
  while (i < str.length) {
    const ch = str[i]
    if (ch === '%') {
      const hex = str.slice(i + 1, i + 3)
      if (hex.length < 2 || !/^[0-9A-Fa-f]{2}$/.test(hex)) {
        throw new UriError(`the ${name} has a truncated percent-encoding`)
