/**
 * The command. `node src/cli.js normalize` normalizes one URI reference per
 * input line; `node src/cli.js resolve` resolves the reference on each line
 * against the base that precedes it. Both print one result per line.
 */

import { normalize, resolve, UriError } from './uri.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function readStdin() {
  const chunks = []
  const fd = 0
  const buf = Buffer.alloc(65536)
  const fs = require('node:fs')
  for (;;) {
    let bytesRead
    try {
      bytesRead = fs.readSync(fd, buf, 0, buf.length, null)
    } catch (err) {
      if (err.code === 'EAGAIN') continue
      if (err.code === 'EOF') break
      throw err
    }
    if (bytesRead === 0) break
    chunks.push(Buffer.from(buf.subarray(0, bytesRead)))
  }
  return Buffer.concat(chunks).toString('utf8')
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'normalize' && args[0] !== 'resolve')) {
    fail('usage: cli.js normalize|resolve')
  }
  const mode = args[0]

  const input = readStdin()
  let lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') {
    lines.pop()
  }

  const results = []
  for (let i = 0; i < lines.length; i++) {
    const n = i + 1
    const line = lines[i]
    try {
      if (mode === 'normalize') {
        results.push(normalize(line))
      } else {
        const idx = line.indexOf(' ')
        if (idx === -1) {
          throw new UriError('expected a base and a reference')
        }
        const base = line.slice(0, idx)
        const ref = line.slice(idx + 1)
        results.push(resolve(base, ref))
      }
    } catch (err) {
      if (err instanceof UriError) {
        fail(`line ${n}: ${err.message}`)
      }
      throw err
    }
  }

  process.stdout.write(results.map((r) => r + '\n').join(''))
  process.exit(0)
}

main()
"}

