{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js merge`, `node src/cli.js merge2` and
 * `node src/cli.js regions` each read three documents from standard input and
 * report the three-way merge of the second into the first and the third.
 */

import { splitLines, splitParts } from './parse.js'
import { buildPlan } from './merge.js'

const MODES = new Set(['merge', 'merge2', 'regions'])

function fail(message) {
  process.stderr.write(`${message}\n`)
  process.exit(2)
}

function readStdin() {
  const chunks = []
  const fd = 0
  const buf = Buffer.alloc(65536)
  const fs = require('node:fs')
  for (;;) {
    let bytesRead
    try {
      bytesRead = fs.readSync(fd, buf, 0, buf.length, null)
    } catch (err) {
      if (err.code === 'EAGAIN') continue
      if (err.code === 'EOF') break
      throw err
    }
    if (bytesRead === 0) break
    chunks.push(Buffer.from(buf.subarray(0, bytesRead)))
  }
  return Buffer.concat(chunks).toString('utf8')
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || !MODES.has(args[0])) {
    fail('error: usage: cli.js merge|merge2|regions')
    return
  }
  const mode = args[0]

  const input = readStdin()
  const lines = splitLines(input)
  const parts = splitParts(lines)
  if (parts.length !== 3) {
    fail('error: expected three parts separated by %%%')
    return
  }
  const [mine, base, theirs] = parts

  const plan = buildPlan(mine, base, theirs)

  let conflict = false
  const out = []

  if (mode === 'regions') {
    for (const seg of plan) {
      if (seg.kind === 'stable') {
        out.push(`stable ${seg.lines.length}\n`)
      } else if (seg.resolution === 'conflict') {
        conflict = true
        out.push(`conflict mine=${seg.mineLines.length} base=${seg.baseLines.length} theirs=${seg.theirsLines.length}\n`)
      } else {
        out.push(`${seg.resolution} ${seg.lines.length}\n`)
      }
    }
  } else {
    for (const seg of plan) {
      if (seg.kind === 'stable') {
        for (const line of seg.lines) out.push(`${line}\n`)
      } else if (seg.resolution === 'conflict') {
        conflict = true
        out.push('<<<<<<< mine\n')
        for (const line of seg.mineLines) out.push(`${line}\n`)
        if (mode === 'merge') {
          out.push('||||||| base\n')
          for (const line of seg.baseLines) out.push(`${line}\n`)
        }
        out.push('=======\n')
        for (const line of seg.theirsLines) out.push(`${line}\n`)
        out.push('>>>>>>> theirs\n')
      } else {
        for (const line of seg.lines) out.push(`${line}\n`)
      }
    }
  }

  process.stdout.write(out.join(''))
  process.exit(conflict ? 1 : 0)
}

main()
"}

