 * URI reference parsing, normalization and resolution per RFC 3986,
 * following the exact rules laid out in the task specification.
 */

export class UriError extends Error {}

const DEFAULT_PORTS = {
  http: '80',
  ws: '80',
  https: '443',
  wss: '443',
  ftp: '21',
}

function asciiLower(str) {
  return str.replace(/[A-Z]/g, (c) => c.toLowerCase())
}

function isUnreservedChar(ch) {
  return /^[A-Za-z0-9\-._~]$/.test(ch)
}

function isHexDigit(ch) {
  return ch !== undefined && /^[0-9A-Fa-f]$/.test(ch)
}

/**
 * Parse a URI reference string into its generic-syntax components,
 * per RFC 3986's ABNF, tracking presence separately from emptiness.
 */
export function parseRef(str) {
  let rest = str

  let hasScheme = false
  let scheme
  let i = 0
  while (i < rest.length && rest[i] !== ':' && rest[i] !== '/' && rest[i] !== '?' && rest[i] !== '#') i++
  if (i < rest.length && rest[i] === ':') {
    hasScheme = true
    scheme = rest.slice(0, i)
    rest = rest.slice(i + 1)
  }

  let hasAuthority = false
  let authorityRaw
  if (rest.startsWith('//')) {
    hasAuthority = true
    let j = 2
    while (j < rest.length && rest[j] !== '/' && rest[j] !== '?' && rest[j] !== '#') j++
    authorityRaw = rest.slice(2, j)
    rest = rest.slice(j)
  }

  let k = 0
  while (k < rest.length && rest[k] !== '?' && rest[k] !== '#') k++
  const path = rest.slice(0, k)
  rest = rest.slice(k)

  let hasQuery = false
  let query
  if (rest[0] === '?') {
    let m = 1
    while (m < rest.length && rest[m] !== '#') m++
    hasQuery = true
    query = rest.slice(1, m)
    rest = rest.slice(m)
  }

  let hasFragment = false
  let fragment
  if (rest[0] === '#') {
    hasFragment = true
    fragment = rest.slice(1)
  }

  const authority = hasAuthority ? parseAuthority(authorityRaw) : undefined

  return { hasScheme, scheme, hasAuthority, authority, path, hasQuery, query, hasFragment, fragment }
}

function parseAuthority(raw) {
  const lastAt = raw.lastIndexOf('@')
  let hasUserinfo = false
  let userinfo
  let hostport = raw
  if (lastAt !== -1) {
    hasUserinfo = true
    userinfo = raw.slice(0, lastAt)
    hostport = raw.slice(lastAt + 1)
  }

  const lastBracket = hostport.lastIndexOf(']')
  const searchFrom = lastBracket + 1
  const colonIdx = hostport.indexOf(':', searchFrom)

  let host
  let hasPort = false
  let port
  if (colonIdx !== -1) {
    host = hostport.slice(0, colonIdx)
    hasPort = true
    port = hostport.slice(colonIdx + 1)
  } else {
    host = hostport
  }

  return { hasUserinfo, userinfo, host, hasPort, port }
}

/**
 * Uppercase %XX hex digits, then replace triplets that encode an
 * unreserved character with that character. Throws UriError on a
 * truncated percent-encoding.
 */
function normalizePercent(str, componentName, lineNo) {
  let out = ''
  for (let i = 0; i < str.length; i++) {
    const c = str[i]
    if (c === '%') {
      const h1 = str[i + 1]
      const h2 = str[i + 2]
      if (!isHexDigit(h1) || !isHexDigit(h2)) {
        throw new UriError(`line ${lineNo}: the ${componentName} has a truncated percent-encoding`)
      }
      const hex = (h1 + h2).toUpperCase()
      const code = parseInt(hex, 16)
      const ch = String.fromCharCode(code)
      if (isUnreservedChar(ch)) {
        out += ch
      } else {
        out += '%' + hex
      }
      i += 2
    } else {
      out += c
    }
  }
  return out
}

/** Remove dot segments from a path per RFC 3986 section 5.2.4. */
function removeDotSegments(path) {
  let input = path
  let output = ''
  while (input.length) {
    if (input.startsWith('../')) {
      input = input.slice(3)
    } else if (input.startsWith('./')) {
      input = input.slice(2)
    } else if (input.startsWith('/./')) {
      input = '/' + input.slice(3)
    } else if (input === '/.') {
      input = '/'
    } else if (input.startsWith('/../')) {
      input = '/' + input.slice(4)
      output = dropLastSegment(output)
    } else if (input === '/..') {
      input = '/'
      output = dropLastSegment(output)
    } else if (input === '.' || input === '..') {
      input = ''
    } else {
      let idx = input[0] === '/' ? 1 : 0
      let next = input.indexOf('/', idx)
      if (next === -1) next = input.length
      output += input.slice(0, next)
      input = input.slice(next)
    }
  }
  return output
}

function dropLastSegment(output) {
  const idx = output.lastIndexOf('/')
  return idx === -1 ? '' : output.slice(0, idx)
}

/**
 * Apply the full normalization procedure to a parsed reference,
 * checking percent-encodings in path, userinfo, host, query,
 * fragment order, and return the normalized component set.
