function normalizeComponents(parsed, lineNo) {
  const hasScheme = parsed.hasScheme
  const scheme = hasScheme ? asciiLower(parsed.scheme) : undefined

  const path0 = normalizePercent(parsed.path, 'path', lineNo)

  let authority
  if (parsed.hasAuthority) {
    const a = parsed.authority
    const userinfo0 = a.hasUserinfo ? normalizePercent(a.userinfo, 'userinfo', lineNo) : undefined
    const host0 = normalizePercent(a.host, 'host', lineNo)
    authority = {
      hasUserinfo: a.hasUserinfo,
      userinfo: userinfo0,
      host: asciiLower(host0),
      hasPort: a.hasPort,
      port: a.port,
