  const query = parsed.hasQuery ? normalizePercent(parsed.query, 'query', lineNo) : undefined
  const fragment = parsed.hasFragment ? normalizePercent(parsed.fragment, 'fragment', lineNo) : undefined

  if (authority && authority.hasPort) {
    const defaultPort = DEFAULT_PORTS[scheme]
    if (authority.port === '' || (defaultPort !== undefined && authority.port === defaultPort)) {
      authority.hasPort = false
      authority.port = undefined
    }
  }

  let path = removeDotSegments(path0)
  if (parsed.hasAuthority && path === '') path = '/'

  return {
    hasScheme,
    scheme,
    hasAuthority: parsed.hasAuthority,
    authority,
    path,
    hasQuery: parsed.hasQuery,
    query,
