/**
 * The command. `node src/cli.js normalize` normalizes one URI reference per
 * input line; `node src/cli.js resolve` resolves the reference on each line
 * against the base that precedes it. Both print one result per line.
 */

import { readFileSync } from 'node:fs'
import { normalize, resolve, UriError } from './uri.js'

function splitRecords(text) {
  if (text === '') return []
  const parts = text.split('\n')
  if (parts[parts.length - 1] === '') parts.pop()
  return parts
}

function main() {
  const args = process.argv.slice(2)
  const mode = args[0]
  if (args.length !== 1 || (mode !== 'normalize' && mode !== 'resolve')) {
    process.stderr.write('error: usage: cli.js normalize|resolve\n')
    process.exit(2)
  }

  const input = readFileSync(0, 'utf8')
  const records = splitRecords(input)
  const results = []

  try {
    for (let idx = 0; idx < records.length; idx++) {
      const lineNo = idx + 1
      const record = records[idx]
      if (mode === 'normalize') {
        results.push(normalize(record, lineNo))
      } else {
        const spaceIdx = record.indexOf(' ')
        if (spaceIdx === -1) {
          throw new UriError(`line ${lineNo}: expected a base and a reference`)
        }
        const base = record.slice(0, spaceIdx)
        const ref = record.slice(spaceIdx + 1)
        results.push(resolve(base, ref, lineNo))
      }
    }
  } catch (err) {
    if (err instanceof UriError) {
      process.stderr.write(`error: ${err.message}\n`)
      process.exit(2)
    }
    throw err
  }

  if (results.length > 0) {
    process.stdout.write(results.join('\n') + '\n')
  }
  process.exit(0)
}

main()
"}

