/**
 * The command. `node src/cli.js tokens` prints every token of the source read
 * from standard input with its position, and `node src/cli.js stats` counts the
 * tokens by kind.
 */

import fs from 'node:fs'
import { scanAll, ScanError } from './lexer.js'

function readStdin() {
  try {
    return fs.readFileSync(0, 'utf8')
  } catch (err) {
    if (err && err.code === 'EAGAIN') {
      // Retry once for pipes that aren't ready yet.
      return fs.readFileSync(0, 'utf8')
    }
    throw err
  }
}

function main() {
  const args = process.argv.slice(2)
  const mode = args.length === 1 ? args[0] : undefined
  if (mode !== 'tokens' && mode !== 'stats') {
    process.stderr.write('error: usage: cli.js tokens|stats\n')
    process.exit(2)
  }

  const source = readStdin()

  let tokens
  try {
    tokens = scanAll(source)
  } catch (err) {
    if (err instanceof ScanError) {
      process.stderr.write(`error: ${err.line}:${err.column}: ${err.reason}\n`)
      process.exit(2)
    }
    throw err
  }

  if (mode === 'tokens') {
    let out = ''
    for (const token of tokens) {
      out += `${token.line}:${token.column} ${token.kind} ${token.text}\n`
    }
    process.stdout.write(out)
  } else {
    const counts = { ident: 0, keyword: 0, number: 0, punct: 0, rawstring: 0, string: 0 }
    for (const token of tokens) counts[token.kind]++
    let out = ''
    for (const kind of ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']) {
      out += `${kind} ${counts[kind]}\n`
    }
    out += `total ${tokens.length}\n`
    process.stdout.write(out)
  }
  process.exit(0)
}

main()
"}

