export class Scanner {
  constructor(source) {
    this.source = source;
    this.pos = 0;
    this.line = 1;
    this.column = 1;
    this.tokens = [];
  }

  peek(offset = 0) {
    return this.source[this.pos + offset];
  }

  advance() {
    const char = this.peek();
    if (char === '\n') {
      this.line++;
      this.column = 1;
    } else if (char === '\t') {
      this.column = Math.floor((this.column - 1 + 4) / 4) * 4 + 1;
    } else if (char !== undefined) {
      this.column++;
    }
    this.pos++;
    return char;
  }

  skipWhitespace() {
    while (this.pos < this.source.length) {
      const char = this.peek();
