 * The command. `node src/cli.js tokens` prints every token of the source read
 * from standard input with its position, and `node src/cli.js stats` counts the
 * tokens by kind.
 */

import { Scanner, ScannerError } from './scanner.js';

const args = process.argv.slice(2);

if (args.length !== 1 || !['tokens', 'stats'].includes(args[0])) {
  process.stderr.write('error: usage: cli.js tokens|stats\n');
  process.exit(2);
}

const mode = args[0];

// Read stdin
let input = '';
process.stdin.setEncoding('utf8');

process.stdin.on('data', (chunk) => {
  input += chunk;
});

process.stdin.on('end', () => {
  try {
    const scanner = new Scanner(input);
    const tokens = scanner.scan();

    if (mode === 'tokens') {
      for (const token of tokens) {
        process.stdout.write(`${token.line}:${token.col} ${token.kind} ${token.body}\n`);
      }
    } else if (mode === 'stats') {
      const counts = {
        ident: 0,
        keyword: 0,
        number: 0,
        punct: 0,
        rawstring: 0,
        string: 0,
      };

      for (const token of tokens) {
        counts[token.kind]++;
      }

      const kinds = ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string'];
      let total = 0;
      for (const kind of kinds) {
        process.stdout.write(`${kind} ${counts[kind]}\n`);
        total += counts[kind];
      }
      process.stdout.write(`total ${total}\n`);
    }

