{"file_path":"src/lexer.js","content":"// The lexer: turns UTF-8 source text into a flat list of positioned tokens.
// Positions count from 1. Tabs advance the column to the next multiple of 4
// plus 1; line feeds move to the next line and reset the column to 1; every
// other code point advances the column by 1.

export class LexError extends Error {
  constructor(line, col, reason) {
    super(reason)
    this.line = line
    this.col = col
    this.reason = reason
  }
}

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])

function isIdentStart(c) {
  return c !== undefined && /[A-Za-z_]/.test(c)
}
function isIdentContinue(c) {
  return c !== undefined && /[A-Za-z0-9_]/.test(c)
}
function isDecDigit(c) {
  return c !== undefined && /[0-9]/.test(c)
}
function isHexDigit(c) {
  return c !== undefined && /[0-9a-fA-F]/.test(c)
}
function isBinDigit(c) {
  return c === '0' || c === '1'
}
function isOctDigit(c) {
  return c !== undefined && /[0-7]/.test(c)
}

const PUNCTS = [
  '==', '!=', '<=', '>=', '&&', '||', '->', '=>',
  '+', '-', '*', '/', '%', '=', '<', '>', '!',
  '(', ')', '{', '}', '[', ']', ',', ';', '.',
]

function nextTabStop(col) {
  return (Math.floor((col - 1) / 4) + 1) * 4 + 1
}

export function scan(input) {
  const chars = Array.from(input)
  const n = chars.length
  let i = 0
  let line = 1
  let col = 1

  function peek(offset = 0) {
    return chars[i + offset]
  }

  function pos() {
    return { line, col }
  }

  function advance() {
    const c = chars[i]
    i++
    if (c === '\n') {
      line++
      col = 1
    } else if (c === '\t') {
      col = nextTabStop(col)
    } else {
      col++
    }
    return c
  }

  function skipWhitespaceAndComments() {
    for (;;) {
      const c = peek()
      if (c === undefined) return
      if (c === ' ' || c === '\t' || c === '\r' || c === '\n') {
        advance()
        continue
      }
      if (c === '/' && peek(1) === '/') {
        advance()
        advance()
        while (peek() !== undefined && peek() !== '\n') advance()
        continue
      }
      if (c === '/' && peek(1) === '*') {
        const start = pos()
        advance()
        advance()
        let depth = 1
        while (depth > 0) {
          if (peek() === undefined) {
            throw new LexError(start.line, start.col, 'unterminated block comment')
          }
          if (peek() === '/' && peek(1) === '*') {
            advance()
            advance()
            depth++
          } else if (peek() === '*' && peek(1) === '/') {
            advance()
            advance()
            depth--
          } else {
            advance()
          }
        }
        continue
      }
      return
    }
  }

  // Consumes a run of digits (matching `predicate`) allowing a single `_`
  // between two digits of the same run. Returns the number of digits
  // consumed (not counting underscores).
  function consumeDigitRun(predicate) {
    let count = 0
    if (!predicate(peek())) return count
    advance()
    count++
    for (;;) {
      if (predicate(peek())) {
        advance()
        count++
      } else if (peek() === '_' && predicate(peek(1))) {
        advance()
        advance()
        count++
      } else {
        break
      }
    }
    return count
  }

  function scanNumber(start) {
    const chunkStart = i
    let malformed = false

    const c0 = peek()
    const c1 = peek(1)
    if (c0 === '0' && c1 !== undefined && /[xXbBoO]/.test(c1)) {
      advance()
      advance()
      const kind = c1.toLowerCase()
      const predicate = kind === 'x' ? isHexDigit : kind === 'b' ? isBinDigit : isOctDigit
      const digits = consumeDigitRun(predicate)
      if (digits === 0) malformed = true
    } else {
      consumeDigitRun(isDecDigit)
      if (peek() === '.' && isDecDigit(peek(1))) {
        advance()
        consumeDigitRun(isDecDigit)
      }
      if (peek() === 'e' || peek() === 'E') {
        const p1 = peek(1)
        const p2 = peek(2)
        if (isDecDigit(p1)) {
          advance()
          consumeDigitRun(isDecDigit)
        } else if ((p1 === '+' || p1 === '-') && isDecDigit(p2)) {
          advance()
          advance()
          consumeDigitRun(isDecDigit)
        }
      }
    }

    let trailing = false
    while (isIdentContinue(peek())) {
      advance()
      trailing = true
    }

    const text = chars.slice(chunkStart, i).join('')
    if (malformed || trailing) {
      throw new LexError(start.line, start.col, `invalid number ${text}`)
    }
    return text
  }

  function hexValue(c) {
    return parseInt(c, 16)
  }

  function scanString(start) {
    advance() // opening quote
    let value = ''
    for (;;) {
      const c = peek()
      if (c === undefined) {
        throw new LexError(start.line, start.col, 'unterminated string')
      }
      if (c === '"') {
        advance()
        break
      }
      if (c === '\n') {
        const p = pos()
        throw new LexError(p.line, p.col, 'newline in string')
      }
      if (c === '\\') {
        const bpos = pos()
        advance()
        const e = peek()
        if (e === undefined) {
          throw new LexError(start.line, start.col, 'unterminated string')
        }
        if (e === 'n') {
          advance()
          value += '\n'
        } else if (e === 't') {
          advance()
          value += '\t'
        } else if (e === 'r') {
          advance()
          value += '\r'
        } else if (e === '\\') {
          advance()
          value += '\\'
        } else if (e === '"') {
          advance()
          value += '"'
        } else if (e === '0') {
          advance()
          value += '\0'
        } else if (e === 'x') {
          advance()
          const h1 = peek()
          const h2 = peek(1)
          if (isHexDigit(h1) && isHexDigit(h2)) {
            advance()
            advance()
            value += String.fromCharCode(hexValue(h1) * 16 + hexValue(h2))
          } else {
            throw new LexError(bpos.line, bpos.col, 'invalid escape \\x')
          }
        } else if (e === 'u') {
          advance()
          if (peek() !== '{') {
            throw new LexError(bpos.line, bpos.col, 'invalid escape \\u')
          }
          advance()
          let hex = ''
          while (isHexDigit(peek())) {
            hex += peek()
            advance()
          }
          if (hex.length === 0 || peek() !== '}') {
            throw new LexError(bpos.line, bpos.col, 'invalid escape \\u')
          }
          advance() // }
          const cp = parseInt(hex, 16)
          if (cp > 0x10ffff) {
            throw new LexError(bpos.line, bpos.col, 'invalid escape \\u')
          }
          value += String.fromCodePoint(cp)
        } else {
          throw new LexError(bpos.line, bpos.col, `invalid escape \\${e}`)
        }
      } else {
        advance()
        value += c
      }
    }
    return value
  }

  function scanRawString(start) {
    advance() // r
    advance() // opening quote
    let value = ''
    for (;;) {
      const c = peek()
      if (c === undefined) {
        throw new LexError(start.line, start.col, 'unterminated string')
      }
      if (c === '"') {
        advance()
        break
      }
      advance()
      value += c
    }
    return value
  }

  const tokens = []

  for (;;) {
    skipWhitespaceAndComments()
    const c = peek()
    if (c === undefined) break

    const start = pos()

    if (c === 'r' && peek(1) === '"') {
      const value = scanRawString(start)
      tokens.push({ line: start.line, col: start.col, kind: 'rawstring', text: JSON.stringify(value) })
      continue
    }

    if (c === '"') {
      const value = scanString(start)
      tokens.push({ line: start.line, col: start.col, kind: 'string', text: JSON.stringify(value) })
      continue
    }

    if (isIdentStart(c)) {
      const chunkStart = i
      advance()
      while (isIdentContinue(peek())) advance()
      const text = chars.slice(chunkStart, i).join('')
      const kind = KEYWORDS.has(text) ? 'keyword' : 'ident'
      tokens.push({ line: start.line, col: start.col, kind, text })
      continue
    }

    if (isDecDigit(c)) {
      const text = scanNumber(start)
      tokens.push({ line: start.line, col: start.col, kind: 'number', text })
      continue
    }

    const two = c + (peek(1) ?? '')
    const punct = PUNCTS.find((p) => p.length === 2 && p === two) ?? PUNCTS.find((p) => p.length === 1 && p === c)
    if (punct !== undefined) {
      for (let k = 0; k < punct.length; k++) advance()
      tokens.push({ line: start.line, col: start.col, kind: 'punct', text: punct })
      continue
    }

    throw new LexError(start.line, start.col, `unexpected character ${c}`)
  }

  return tokens
}
"}

