    // Record the gap before this match as a change
    if (docIdx < matchDoc || baseIdx < matchBase) {
      changes.push({
        baseStart: baseIdx,
        baseEnd: matchBase,
        docStart: docIdx,
        docEnd: matchDoc,
        isTheirs
      })
    }
    docIdx = matchDoc + 1
    baseIdx = matchBase + 1
  }

  // Record any remaining gap as a change
  if (docIdx < doc.length || baseIdx < base.length) {
    changes.push({
      baseStart: baseIdx,
      baseEnd: base.length,
      docStart: docIdx,
      docEnd: doc.length,
      isTheirs
    })
  }

  return { changes, matches }
}

// Get changes from both sides
const mineResult = getChanges(mine, base, false)
const theirsResult = getChanges(theirs, base, true)
const mineChanges = mineResult.changes
const theirsChanges = theirsResult.changes
const mineMatches = mineResult.matches
const theirsMatches = theirsResult.matches

// Merge changes by base position
const allChanges = [...mineChanges, ...theirsChanges]
  .sort((a, b) => {
    if (a.baseStart !== b.baseStart) return a.baseStart - b.baseStart
    // mine changes before theirs when starting at same place
    if (a.isTheirs && !b.isTheirs) return 1
    if (!a.isTheirs && b.isTheirs) return -1
    return 0
  })

// Group changes into regions (both stable and changed)
const regions = []

if (allChanges.length === 0) {
  // No changes - the entire thing is stable
  if (base.length > 0) {
    regions.push({
      baseStart: 0,
      baseEnd: base.length,
      changes: []
    })
  }
} else {
  // Add stable region before first change
  if (allChanges[0].baseStart > 0) {
    regions.push({
      baseStart: 0,
      baseEnd: allChanges[0].baseStart,
      changes: []
    })
  }

  // Process changes
  let i = 0
  while (i < allChanges.length) {
    const regionStart = allChanges[i].baseStart
    let regionEnd = allChanges[i].baseEnd
    const regionChanges = [allChanges[i]]
    i++

    // Absorb overlapping changes
    while (i < allChanges.length && allChanges[i].baseStart <= regionEnd) {
      regionEnd = Math.max(regionEnd, allChanges[i].baseEnd)
      regionChanges.push(allChanges[i])
      i++
    }

    regions.push({
      baseStart: regionStart,
      baseEnd: regionEnd,
      changes: regionChanges
    })

    // Add stable region after this changed region (if there's space before next change)
    if (i < allChanges.length && allChanges[i].baseStart > regionEnd) {
      regions.push({
        baseStart: regionEnd,
        baseEnd: allChanges[i].baseStart,
        changes: []
      })
    }
  }

  // Add stable region after last change
  const lastChange = allChanges[allChanges.length - 1]
  if (lastChange.baseEnd < base.length) {
    regions.push({
      baseStart: lastChange.baseEnd,
      baseEnd: base.length,
      changes: []
    })
  }
}

// Helper to get doc lines corresponding to base lines using matches
function getDocLinesForBaseRange(baseStart, baseEnd, matches, doc) {
  const lines = []
  let docIdx = 0
  let baseIdx = 0
  let matchIdx = 0

  while (baseIdx < baseEnd) {
    if (matchIdx < matches.length && matches[matchIdx][1] === baseIdx) {
      // This base line is matched
      const docMatchIdx = matches[matchIdx][0]
      lines.push(doc[docMatchIdx])
      docIdx = docMatchIdx + 1
      baseIdx += 1
      matchIdx += 1
    } else if (baseIdx >= baseStart) {
      // We're in the range and this line isn't matched - it's been deleted
      baseIdx += 1
    } else {
      // We haven't reached the start of the range yet
      if (matchIdx < matches.length) {
        docIdx = matches[matchIdx][0] + 1
        baseIdx = matches[matchIdx][1] + 1
        matchIdx += 1
      } else {
        break
      }
    }
  }

  // Extract only the lines corresponding to our range
  const result = []
  baseIdx = 0
  matchIdx = 0
  for (; matchIdx < matches.length && matches[matchIdx][1] < baseStart; matchIdx++) {
    baseIdx = matches[matchIdx][1] + 1
  }

  // Now collect lines for the range [baseStart, baseEnd)
  for (; matchIdx < matches.length && matches[matchIdx][1] < baseEnd; matchIdx++) {
    if (matches[matchIdx][1] >= baseStart) {
      result.push(doc[matches[matchIdx][0]])
    }
  }

  return result
}

// Helper function to compute resolved lines for a side with adjustments
function getResolvedLines(doc, changes, region, matches) {
  if (changes.length === 0) {
    // No changes from this side - use matched lines from this side
    return getDocLinesForBaseRange(region.baseStart, region.baseEnd, matches, doc)
  } else if (changes.length === 1) {
    // Single change: use the doc lines from the change
    const change = changes[0]
    return doc.slice(change.docStart, change.docEnd)
  } else {
    // Multiple changes: apply adjustment logic from spec
    const minDocStart = Math.min(...changes.map(c => c.docStart))
    const minBaseStart = Math.min(...changes.map(c => c.baseStart))
    const maxDocEnd = Math.max(...changes.map(c => c.docEnd))
    const maxBaseEnd = Math.max(...changes.map(c => c.baseEnd))

    // Adjust start: include lines before the first change
    const moveBackAmount = minBaseStart - region.baseStart
    const adjustedStart = Math.max(0, minDocStart - moveBackAmount)

    // Adjust end: include lines after the last change
    const moveForwardAmount = region.baseEnd - maxBaseEnd
    const adjustedEnd = Math.min(doc.length, maxDocEnd + moveForwardAmount)

    return doc.slice(adjustedStart, adjustedEnd)
  }
}

// Resolve each region
const resolvedRegions = []
let hasConflict = false

for (const region of regions) {
  const mineChangesInRegion = region.changes.filter(c => !c.isTheirs)
  const theirsChangesInRegion = region.changes.filter(c => c.isTheirs)

  const baseResolved = base.slice(region.baseStart, region.baseEnd)
  const mineResolved = getResolvedLines(mine, mineChangesInRegion, region, mineMatches)
  const theirsResolved = getResolvedLines(theirs, theirsChangesInRegion, region, theirsMatches)

  let resolved
  let isConflict = false
  let regionType = 'stable'

  if (region.changes.length === 0) {
    // Stable region - no changes on either side
    resolved = mineResolved  // Should be same as base and theirs
    regionType = 'stable'
  } else if (region.changes.length === 1) {
    // Only one side changed
    const change = region.changes[0]
    if (change.isTheirs) {
      resolved = theirsResolved
      regionType = 'theirs'
    } else {
      resolved = mineResolved
      regionType = 'mine'
    }
  } else {
    // Both sides may have changed
    if (JSON.stringify(mineResolved) === JSON.stringify(theirsResolved)) {
      // Both made the same change
      resolved = mineResolved
      regionType = 'both'
    } else if (JSON.stringify(mineResolved) === JSON.stringify(baseResolved)) {
      // Mine is same as base, so take theirs
      resolved = theirsResolved
      regionType = 'theirs'
    } else if (JSON.stringify(theirsResolved) === JSON.stringify(baseResolved)) {
      // Theirs is same as base, so take mine
      resolved = mineResolved
      regionType = 'mine'
    } else {
      // Conflict - both sides changed differently
      isConflict = true
      resolved = null
    }
  }

  resolvedRegions.push({
    type: regionType,
    resolved,
    isConflict,
    mineLines: mineResolved,
    baseLines: baseResolved,
    theirsLines: theirsResolved,
    lineCount: resolved ? resolved.length : null
  })

  if (isConflict) hasConflict = true
}

// Output based on mode
function outputMerge() {
  const output = []
  for (const region of resolvedRegions) {
    if (region.isConflict) {
      output.push('<<<<<<< mine')
      output.push(...region.mineLines)
      output.push('||||||| base')
      output.push(...region.baseLines)
      output.push('=======')
      output.push(...region.theirsLines)
      output.push('>>>>>>> theirs')
    } else {
      output.push(...region.resolved)
    }
  }
  return output.length > 0 ? output.join('\n') + '\n' : ''
}

function outputMerge2() {
  const output = []
  for (const region of resolvedRegions) {
    if (region.isConflict) {
      output.push('<<<<<<< mine')
      output.push(...region.mineLines)
      output.push('=======')
      output.push(...region.theirsLines)
      output.push('>>>>>>> theirs')
    } else {
      output.push(...region.resolved)
    }
  }
  return output.length > 0 ? output.join('\n') + '\n' : ''
}

function outputRegions() {
  const output = []
  for (const region of resolvedRegions) {
    if (region.isConflict) {
      output.push(`conflict mine=${region.mineLines.length} base=${region.baseLines.length} theirs=${region.theirsLines.length}`)
    } else {
      output.push(`${region.type} ${region.lineCount}`)
    }
  }
  return output.length > 0 ? output.join('\n') + '\n' : ''
}

if (mode === 'merge') {
  process.stdout.write(outputMerge())
} else if (mode === 'merge2') {
  process.stdout.write(outputMerge2())
} else if (mode === 'regions') {
  process.stdout.write(outputRegions())
}

process.exit(hasConflict ? 1 : 0)
"}

