/**
 * Simulates the build graph on a fixed number of workers.
 *
 * While a worker is free at the current instant and some task is ready
 * (every dependency has finished at or before that instant), the ready
 * task with the greatest priority (ties broken by ascending name) starts
 * on the free worker with the smallest index. When nothing more can start,
 * time advances to the next instant a worker frees up.
 *
 * Returns { workerLogs, makespan } where workerLogs[i] is an array of
 * { name, start, finish } in the order worker i ran them.
 */
export function pack(tasks, workerCount) {
  const priorities = computePriorities(tasks)
  const names = [...tasks.keys()].sort()

  const workerFree = new Array(workerCount).fill(0)
  const workerLogs = Array.from({ length: workerCount }, () => [])

  const finishTime = new Map()
  const started = new Set()
  let remaining = names.length

  let currentTime = 0
  let makespan = 0

  const isReady = (name, time) => {
    const task = tasks.get(name)
    for (const dep of task.deps) {
      const f = finishTime.get(dep)
      if (f === undefined || f > time) return false
    }
    return true
  }

  while (remaining > 0) {
    let progressed = true
    while (progressed) {
      progressed = false
      let freeWorker = -1
      for (let i = 0; i < workerCount; i++) {
        if (workerFree[i] <= currentTime) { freeWorker = i; break }
      }
      if (freeWorker === -1) break

      let best = null
      for (const name of names) {
        if (started.has(name)) continue
        if (!isReady(name, currentTime)) continue
        if (
          best === null ||
          priorities.get(name) > priorities.get(best) ||
          (priorities.get(name) === priorities.get(best) && name < best)
        ) {
          best = name
        }
      }
      if (best === null) break

      const task = tasks.get(best)
      const start = currentTime
      const finish = start + task.cost
      started.add(best)
      finishTime.set(best, finish)
      workerLogs[freeWorker].push({ name: best, start, finish })
      workerFree[freeWorker] = finish
      remaining -= 1
      if (finish > makespan) makespan = finish
      progressed = true
    }

    if (remaining === 0) break

    let nextTime = Infinity
    for (let i = 0; i < workerCount; i++) {
      if (workerFree[i] > currentTime && workerFree[i] < nextTime) {
        nextTime = workerFree[i]
      }
    }
    if (nextTime === Infinity) {
      // Should not happen for an acyclic graph, but avoid an infinite loop.
      break
    }
    currentTime = nextTime
  }

  return { workerLogs, makespan }
}
"}

