{"file_path":"src/limiter.js","content":"/**
 * Rate limiter implementation with token buckets and sliding windows.
 */

export class Limiter {
  constructor(buckets, windows, routes) {
    this.buckets = buckets
    this.windows = windows
    this.routes = routes

    // State tracking per policy and key
    this.bucketStates = new Map() // Map of policyName -> Map of key -> { tokens, lastTick }
    this.windowStates = new Map() // Map of policyName -> Map of key -> { ticks: [] }

    // Initialize state maps
    for (const [name] of buckets) {
      this.bucketStates.set(name, new Map())
    }
    for (const [name] of windows) {
      this.windowStates.set(name, new Map())
    }
  }

  processEvents(events, mode) {
    const results = []
    const keyStats = new Map() // Map of key -> { allowed, denied }
    let totalAllowed = 0
    let totalDenied = 0

    for (const event of events) {
      const { tick, key } = event

      // Find the matching route for this key
      const route = this.findRoute(key)

      if (route === null) {
        // No route matches, always allow
        results.push(`${tick} ${key} allow`)

        if (mode === 'summary') {
          if (!keyStats.has(key)) {
            keyStats.set(key, { allowed: 0, denied: 0 })
          }
          keyStats.get(key).allowed++
          totalAllowed++
        }
      } else {
        // Check policies on this route
        const policies = route.policies

        // First, advance all policies to this tick
        for (const policyName of policies) {
          this.advancePolicy(policyName, key, tick)
        }

        // Then, check if all policies allow
        let firstDeniedPolicy = null
        let allAllow = true

        for (const policyName of policies) {
          if (!this.checkPolicy(policyName, key)) {
            firstDeniedPolicy = policyName
            allAllow = false
            break
          }
        }

        if (allAllow) {
          // Record in all policies
          for (const policyName of policies) {
            this.recordPolicy(policyName, key, tick)
          }
          results.push(`${tick} ${key} allow`)

          if (mode === 'summary') {
            if (!keyStats.has(key)) {
              keyStats.set(key, { allowed: 0, denied: 0 })
            }
            keyStats.get(key).allowed++
            totalAllowed++
          }
        } else {
          // Denied
          results.push(`${tick} ${key} deny ${firstDeniedPolicy}`)

          if (mode === 'summary') {
            if (!keyStats.has(key)) {
              keyStats.set(key, { allowed: 0, denied: 0 })
            }
            keyStats.get(key).denied++
            totalDenied++
          }
        }
      }
    }

    if (mode === 'replay') {
      return results
    } else {
      // summary mode
      const output = []

      // Sort keys and output stats
      const sortedKeys = Array.from(keyStats.keys()).sort()
      for (const key of sortedKeys) {
        const stats = keyStats.get(key)
        output.push(`${key} allowed=${stats.allowed} denied=${stats.denied}`)
      }

      output.push(`total allowed=${totalAllowed} denied=${totalDenied}`)
      return output
    }
  }

  findRoute(key) {
    // Find the route with the longest matching prefix
    let bestRoute = null
    let bestPrefixLen = -1

    for (const route of this.routes) {
      if (key.startsWith(route.prefix) && route.prefix.length > bestPrefixLen) {
        bestRoute = route
