import { resolveWord, resolveRange } from './range.js'
import { FUNCTIONS } from './formula-parser.js'

const COMPARE_OPS = new Set(['=', '<>', '<', '<=', '>', '>='])
const MULTI_ARG_FUNCTIONS = new Set(['SUM', 'MIN', 'MAX', 'COUNT', 'AVG'])

class Evaluator {
  constructor(compiled) {
    this.compiled = compiled
    this.cache = new Map()
    this.stack = new Set()
  }

  evaluate(addr) {
    if (this.cache.has(addr)) return this.cache.get(addr)
    if (this.stack.has(addr)) return mkErr('#CYCLE!')
    const cell = this.compiled.get(addr)
    if (!cell) {
      const v = mkNum(0)
      this.cache.set(addr, v)
      return v
    }
    this.stack.add(addr)
    let result
    try {
      if (cell.kind === 'literal') {
        result = parseLiteral(cell.content)
      } else if (!cell.ok) {
        result = mkErr('#ERR!')
      } else {
        result = this.evalNode(cell.ast)
      }
    } finally {
      this.stack.delete(addr)
    }
    this.cache.set(addr, result)
    return result
  }

  evalNode(node) {
    switch (node.kind) {
      case 'number':
        return mkNum(node.value)
      case 'bool':
        return mkBool(node.value)
      case 'address': {
        const addr = resolveWord(node.word)
        if (addr === null) return mkErr('#REF!')
        return this.evaluate(addr)
      }
      case 'unop':
        return this.evalUnop(node)
      case 'binop':
        return this.evalBinop(node)
      case 'call':
        return this.evalCall(node)
      default:
        return mkErr('#ERR!')
    }
  }

  evalUnop(node) {
    const operand = this.evalNode(node.operand)
    if (operand.t === 'err') return operand
    const coerced = coerceNumber(operand)
    if (coerced.t === 'err') return coerced
    const v = node.op === '-' ? -coerced.v : coerced.v
    if (!isFinite(v)) return mkErr('#DIV/0!')
    return mkNum(v)
  }

  evalBinop(node) {
    const left = this.evalNode(node.left)
    const right = this.evalNode(node.right)
    if (COMPARE_OPS.has(node.op)) {
      if (left.t === 'err') return left
      if (right.t === 'err') return right
      const cmp = compareValues(left, right)
      let result
      switch (node.op) {
        case '=':
          result = cmp === 0
          break
        case '<>':
          result = cmp !== 0
          break
        case '<':
          result = cmp < 0
          break
        case '<=':
          result = cmp <= 0
          break
        case '>':
          result = cmp > 0
          break
        case '>=':
          result = cmp >= 0
          break
      }
      return mkBool(result)
    }
    if (left.t === 'err') return left
    if (right.t === 'err') return right
    const ln = coerceNumber(left)
    if (ln.t === 'err') return ln
    const rn = coerceNumber(right)
    if (rn.t === 'err') return rn
    let v
    switch (node.op) {
      case '+':
        v = ln.v + rn.v
        break
      case '-':
        v = ln.v - rn.v
        break
      case '*':
        v = ln.v * rn.v
        break
      case '/':
        if (rn.v === 0) return mkErr('#DIV/0!')
        v = ln.v / rn.v
        break
      case '^':
        v = Math.pow(ln.v, rn.v)
        break
    }
