    for (const arg of node.args) {
      values.push(...this.evalArgValues(arg))
    }
    const err = values.find((v) => v.t === 'err')
    if (err) return err

    if (name === 'COUNT') {
      const count = values.filter((v) => v.t === 'num').length
      return mkNum(count)
    }

    const nums = []
    for (const v of values) {
      const c = coerceNumber(v)
      if (c.t === 'err') return c
      nums.push(c.v)
    }

    let result
    switch (name) {
      case 'SUM':
        result = nums.reduce((a, b) => a + b, 0)
        break
      case 'MIN':
        result = Math.min(...nums)
        break
      case 'MAX':
        result = Math.max(...nums)
        break
      case 'AVG':
        result = nums.reduce((a, b) => a + b, 0) / nums.length
        break
      case 'ABS':
        result = Math.abs(nums[0])
        break
    }
    if (!isFinite(result)) return mkErr('#DIV/0!')
    return mkNum(result)
  }
}

